package com.appiumsetup.architecture;

import io.appium.java_client.AppiumDriver;
import org.openqa.selenium.remote.DesiredCapabilities;
import java.net.URL;

/**
 * This class demonstrates the complete flow of how a simple
 * Appium command travels through the architecture layers.
 * Understanding this flow is essential for debugging and
 * optimizing your mobile automation tests.
 */
public class ArchitectureFlowDemo {

    public static void main(String[] args) throws Exception {
        System.out.println("🚀 Starting Appium Architecture Demonstration");
        System.out.println("==============================================\n");

        // Step 1: Configure what we want to automate
        System.out.println("1. CLIENT LAYER: Configuring Desired Capabilities");
        DesiredCapabilities caps = new DesiredCapabilities();
        caps.setCapability("platformName", "Android");
        caps.setCapability("automationName", "UiAutomator2");
        caps.setCapability("deviceName", "Pixel_6");
        caps.setCapability("appPackage", "com.android.calculator2");
        caps.setCapability("appActivity", "com.android.calculator2.Calculator");

        System.out.println("   Capabilities configured for Android Calculator app\n");

        // Step 2: Define where to send commands
        System.out.println("2. CLIENT LAYER: Creating connection to Appium Server");
        URL appiumServerUrl = new URL("http://127.0.0.1:4723");
        System.out.println("   Server URL: " + appiumServerUrl);
        System.out.println("   Default port: 4723\n");

        // Step 3: Create driver instance (this establishes the session)
        System.out.println("3. CLIENT → SERVER: Creating new session");
        System.out.println("   Sending HTTP POST to: " + appiumServerUrl + "/session");
        System.out.println("   With JSON payload containing capabilities\n");

        // In real code, we would create the driver here:
        // AppiumDriver driver = new AppiumDriver(appiumServerUrl, caps);

        System.out.println("4. SERVER LAYER: Processing session creation");
        System.out.println("   • Validates capabilities");
        System.out.println("   • Checks if requested driver (UiAutomator2) is available");
        System.out.println("   • Initializes driver with device/emulator");
        System.out.println("   • Creates unique session ID\n");

        System.out.println("5. DRIVER LAYER: UiAutomator2 driver initialization");
        System.out.println("   • Checks ADB connection");
        System.out.println("   • Installs/launches app on device");
        System.out.println("   • Starts UiAutomator2 server on device\n");

        System.out.println("6. DEVICE LAYER: App launch and automation setup");
        System.out.println("   • Calculator app launches on device/emulator");
        System.out.println("   • UiAutomator2 service starts accepting commands\n");

        // Demonstrate what happens when we find an element
        demonstrateElementFinding();

        System.out.println("\n✅ Architecture demonstration complete!");
        System.out.println("\nKey Takeaways:");
        System.out.println("• Each layer has specific responsibilities");
        System.out.println("• Communication flows through standardized protocols");
        System.out.println("• Understanding this flow helps diagnose where failures occur");
    }

    private static void demonstrateElementFinding() {
        System.out.println("7. EXAMPLE: Finding an element (digit 5 button)");
        System.out.println("   Test code: driver.findElement(By.id(\"digit_5\"))");
        System.out.println("\n   What happens behind the scenes:\n");

        System.out.println("   a) CLIENT: Creates JSON payload");
        System.out.println("      {\"using\": \"id\", \"value\": \"digit_5\"}");
        System.out.println("\n   b) CLIENT → SERVER: HTTP POST request");
        System.out.println("      POST /session/{session-id}/element");
        System.out.println("      Content-Type: application/json");
        System.out.println("\n   c) SERVER: Receives and validates request");
        System.out.println("      • Verifies session exists");
        System.out.println("      • Routes to UiAutomator2 driver");
        System.out.println("\n   d) DRIVER: Executes findElement on device");
        System.out.println("      • Uses UiAutomator2 framework");
        System.out.println("      • Searches for resource-id: digit_5");
        System.out.println("\n   e) DEVICE: Returns element information");
        System.out.println("      • Element bounds, attributes, clickable state");
        System.out.println("\n   f) SERVER → CLIENT: HTTP response");
        System.out.println("      {\"value\": {\"ELEMENT\": \"element-ref-123\"}}");
        System.out.println("\n   g) CLIENT: Creates WebElement wrapper");
        System.out.println("      • Stores element reference");
        System.out.println("      • Enables subsequent interactions (click, getText, etc.)");
    }
}

package com.appiumsetup.config;

import io.appium.java_client.remote.AndroidMobileCapabilityType;
import io.appium.java_client.remote.IOSMobileCapabilityType;
import io.appium.java_client.remote.MobileCapabilityType;
import org.openqa.selenium.remote.DesiredCapabilities;

import java.io.File;
import java.util.HashMap;
import java.util.Map;
import java.util.Properties;

/**
 * Comprehensive capabilities management system for enterprise mobile automation.
 * This class demonstrates professional patterns for capability configuration,
 * including validation, environment-specific overrides, and security best practices.
 */
public class EnterpriseCapabilitiesManager {

    // Configuration constants loaded from properties or environment
    private static final Properties CONFIG = loadConfiguration();

    // Platform constants
    private static final String PLATFORM_ANDROID = "ANDROID";
    private static final String PLATFORM_IOS = "IOS";

    // Environment constants
    private static final String ENV_DEV = "DEV";
    private static final String ENV_TEST = "TEST";
    private static final String ENV_STAGING = "STAGING";
    private static final String ENV_PROD = "PROD";

    // Test type constants
    private static final String TEST_TYPE_SMOKE = "SMOKE";
    private static final String TEST_TYPE_REGRESSION = "REGRESSION";
    private static final String TEST_TYPE_PERFORMANCE = "PERFORMANCE";
    private static final String TEST_TYPE_ACCESSIBILITY = "ACCESSIBILITY";

    /**
     * Main entry point: Get capabilities for a specific test scenario
     */
    public static DesiredCapabilities getCapabilities(String platform, 
                                                     String environment,
                                                     String testType,
                                                     Map<String, Object> overrides) {

        // Validate inputs
        validateInputs(platform, environment, testType);

        // Get base capabilities for the platform
        DesiredCapabilities caps = getBaseCapabilities(platform);

        // Apply environment-specific configurations
        applyEnvironmentConfig(caps, environment);

        // Apply test type optimizations
        applyTestTypeConfig(caps, testType);

        // Apply any runtime overrides
        if (overrides != null && !overrides.isEmpty()) {
            applyOverrides(caps, overrides);
        }

        // Validate final capability set
        validateCapabilities(caps);

        return caps;
    }

    /**
     * Get base capabilities for a platform
     */
    private static DesiredCapabilities getBaseCapabilities(String platform) {
        DesiredCapabilities caps = new DesiredCapabilities();

        if (PLATFORM_ANDROID.equalsIgnoreCase(platform)) {
            configureAndroidBaseCapabilities(caps);
        } else if (PLATFORM_IOS.equalsIgnoreCase(platform)) {
            configureIOSBaseCapabilities(caps);
        }

        return caps;
    }

    /**
     * Configure Android-specific base capabilities
     */
    private static void configureAndroidBaseCapabilities(DesiredCapabilities caps) {
        // Required capabilities
        caps.setCapability(MobileCapabilityType.PLATFORM_NAME, "Android");
        caps.setCapability(MobileCapabilityType.AUTOMATION_NAME, "UiAutomator2");

        // Performance defaults
        caps.setCapability(MobileCapabilityType.NEW_COMMAND_TIMEOUT, 300);
        caps.setCapability(AndroidMobileCapabilityType.AUTO_GRANT_PERMISSIONS, true);
        caps.setCapability(AndroidMobileCapabilityType.IGNORE_UNIMPORTANT_VIEWS, true);

        // Input settings
        caps.setCapability(AndroidMobileCapabilityType.UNICODE_KEYBOARD, true);
        caps.setCapability(AndroidMobileCapabilityType.RESET_KEYBOARD, true);

        // Reset behavior
        caps.setCapability(MobileCapabilityType.NO_RESET, false);
        caps.setCapability(MobileCapabilityType.FULL_RESET, false);

        // Debugging (disabled by default, enabled via environment)
        caps.setCapability(MobileCapabilityType.PRINT_PAGE_SOURCE_ON_FIND_FAILURE, false);

        // Appium 2.0+ specific (using appium: prefix)
        caps.setCapability("appium:enforceXPath1", false);
        caps.setCapability("appium:disableWindowAnimation", true);
    }

    /**
     * Configure iOS-specific base capabilities
     */
    private static void configureIOSBaseCapabilities(DesiredCapabilities caps) {
        // Required capabilities
        caps.setCapability(MobileCapabilityType.PLATFORM_NAME, "iOS");
        caps.setCapability(MobileCapabilityType.AUTOMATION_NAME, "XCUITest");

        // Performance defaults
        caps.setCapability(MobileCapabilityType.NEW_COMMAND_TIMEOUT, 300);
        caps.setCapability(IOSMobileCapabilityType.AUTO_ACCEPT_ALERTS, true);
        caps.setCapability(IOSMobileCapabilityType.REDUCE_MOTION, true);

        // WebDriverAgent configuration
        caps.setCapability(IOSMobileCapabilityType.WDA_LOCAL_PORT, 8100);
        caps.setCapability(IOSMobileCapabilityType.USE_NEW_WDA, true);
        caps.setCapability(IOSMobileCapabilityType.WDA_LAUNCH_TIMEOUT, 120000);

        // Reset behavior
        caps.setCapability(MobileCapabilityType.NO_RESET, false);
        caps.setCapability(MobileCapabilityType.FULL_RESET, false);

        // Debugging (disabled by default)
        caps.setCapability(IOSMobileCapabilityType.SHOW_XCODE_LOG, false);

        // Safari web view support
        caps.setCapability(IOSMobileCapabilityType.INCLUDE_SAFARI_IN_WEB_VIEWS, true);
        caps.setCapability(IOSMobileCapabilityType.START_IWDP, true);
    }

    /**
     * Apply environment-specific configurations
     */
    private static void applyEnvironmentConfig(DesiredCapabilities caps, String environment) {
        switch (environment.toUpperCase()) {
            case ENV_DEV:
                // Development environment: Fast, preserves state
                caps.setCapability(MobileCapabilityType.NO_RESET, true);
                caps.setCapability(MobileCapabilityType.FULL_RESET, false);
                caps.setCapability(MobileCapabilityType.NEW_COMMAND_TIMEOUT, 600); // Longer for debugging
                break;

            case ENV_TEST:
            case ENV_STAGING:
                // Test/Staging: Balanced approach
                caps.setCapability(MobileCapabilityType.NO_RESET, false);
                caps.setCapability(MobileCapabilityType.FULL_RESET, false);
                caps.setCapability(MobileCapabilityType.NEW_COMMAND_TIMEOUT, 300);
                break;

            case ENV_PROD:
                // Production-like: Clean state, security focused
                caps.setCapability(MobileCapabilityType.NO_RESET, false);
                caps.setCapability(MobileCapabilityType.FULL_RESET, true);
                caps.setCapability(MobileCapabilityType.NEW_COMMAND_TIMEOUT, 180);
                // Disable auto permissions in prod-like tests
                if (caps.getCapability(MobileCapabilityType.PLATFORM_NAME).equals("Android")) {
                    caps.setCapability(AndroidMobileCapabilityType.AUTO_GRANT_PERMISSIONS, false);
                }
                break;
        }

        // Set app path based on environment
        String appPath = getAppPathForEnvironment(
            (String) caps.getCapability(MobileCapabilityType.PLATFORM_NAME),
            environment
        );

        if (appPath != null && new File(appPath).exists()) {
            caps.setCapability(MobileCapabilityType.APP, appPath);
        }
    }

    /**
     * Apply optimizations for different test types
     */
    private static void applyTestTypeConfig(DesiredCapabilities caps, String testType) {
        switch (testType.toUpperCase()) {
            case TEST_TYPE_SMOKE:
                // Smoke tests: Fast execution
                caps.setCapability(MobileCapabilityType.NEW_COMMAND_TIMEOUT, 120);
                caps.setCapability("appium:skipUnlock", true);
                caps.setCapability("appium:skipDeviceInitialization", true);
                break;

            case TEST_TYPE_REGRESSION:
                // Regression tests: Comprehensive
                caps.setCapability(MobileCapabilityType.PRINT_PAGE_SOURCE_ON_FIND_FAILURE, true);
                caps.setCapability("appium:enablePerformanceLogging", true);
                break;

            case TEST_TYPE_PERFORMANCE:
                // Performance tests: Detailed metrics
                caps.setCapability("appium:enablePerformanceLogging", true);
                caps.setCapability("appium:disableWindowAnimation", false); // Keep animations for realistic timing
                caps.setCapability(MobileCapabilityType.NEW_COMMAND_TIMEOUT, 600);
                break;

            case TEST_TYPE_ACCESSIBILITY:
                // Accessibility tests: Focus on accessibility features
                caps.setCapability("appium:accessibilityChecks", true);
                caps.setCapability("appium:nativeWebScreenshot", true);
                break;
        }
    }

    /**
     * Builder pattern for fluent capability configuration
     */
    public static class CapabilityBuilder {
        private final DesiredCapabilities caps = new DesiredCapabilities();
        private String platform;

        public CapabilityBuilder forPlatform(String platform) {
            this.platform = platform.toUpperCase();
            if (PLATFORM_ANDROID.equals(this.platform)) {
                caps.setCapability(MobileCapabilityType.PLATFORM_NAME, "Android");
                caps.setCapability(MobileCapabilityType.AUTOMATION_NAME, "UiAutomator2");
            } else if (PLATFORM_IOS.equals(this.platform)) {
                caps.setCapability(MobileCapabilityType.PLATFORM_NAME, "iOS");
                caps.setCapability(MobileCapabilityType.AUTOMATION_NAME, "XCUITest");
            }
            return this;
        }

        public CapabilityBuilder withApp(String appPath) {
            if (appPath != null && new File(appPath).exists()) {
                caps.setCapability(MobileCapabilityType.APP, new File(appPath).getAbsolutePath());
            }
            return this;
        }

        public CapabilityBuilder withDevice(String deviceName) {
            caps.setCapability(MobileCapabilityType.DEVICE_NAME, deviceName);
            return this;
        }

        public CapabilityBuilder withUdid(String udid) {
            caps.setCapability(MobileCapabilityType.UDID, udid);
            return this;
        }

        public CapabilityBuilder withAvd(String avdName) {
            if (PLATFORM_ANDROID.equals(platform)) {
                caps.setCapability(AndroidMobileCapabilityType.AVD, avdName);
            }
            return this;
        }

        public CapabilityBuilder withResetBehavior(boolean noReset, boolean fullReset) {
            caps.setCapability(MobileCapabilityType.NO_RESET, noReset);
            caps.setCapability(MobileCapabilityType.FULL_RESET, fullReset);
            return this;
        }

        public CapabilityBuilder withTimeout(int seconds) {
            caps.setCapability(MobileCapabilityType.NEW_COMMAND_TIMEOUT, seconds);
            return this;
        }

        public CapabilityBuilder withParallelPort(int port) {
            if (PLATFORM_ANDROID.equals(platform)) {
                caps.setCapability(AndroidMobileCapabilityType.SYSTEM_PORT, port);
            } else if (PLATFORM_IOS.equals(platform)) {
                caps.setCapability(IOSMobileCapabilityType.WDA_LOCAL_PORT, port);
            }
            return this;
        }

        public CapabilityBuilder withCustomCapability(String key, Object value) {
            caps.setCapability(key, value);
            return this;
        }

        public DesiredCapabilities build() {
            // Apply defaults if not set
            if (!caps.asMap().containsKey(MobileCapabilityType.NEW_COMMAND_TIMEOUT)) {
                caps.setCapability(MobileCapabilityType.NEW_COMMAND_TIMEOUT, 300);
            }

            // Platform-specific defaults
            if (PLATFORM_ANDROID.equals(platform)) {
                if (!caps.asMap().containsKey(AndroidMobileCapabilityType.AUTO_GRANT_PERMISSIONS)) {
                    caps.setCapability(AndroidMobileCapabilityType.AUTO_GRANT_PERMISSIONS, true);
                }
            } else if (PLATFORM_IOS.equals(platform)) {
                if (!caps.asMap().containsKey(IOSMobileCapabilityType.AUTO_ACCEPT_ALERTS)) {
                    caps.setCapability(IOSMobileCapabilityType.AUTO_ACCEPT_ALERTS, true);
                }
            }

            validateCapabilities(caps);
            return caps;
        }
    }

    /**
     * Get capabilities for parallel execution across multiple devices
     */
    public static Map<String, DesiredCapabilities> getParallelCapabilities(
            String platform, 
            int deviceCount,
            String environment) {

        Map<String, DesiredCapabilities> allCaps = new HashMap<>();

        if (PLATFORM_ANDROID.equalsIgnoreCase(platform)) {
            // For Android: Use different system ports
            String[] avds = getAvailableAvds();

            for (int i = 0; i < Math.min(deviceCount, avds.length); i++) {
                DesiredCapabilities caps = getCapabilities(platform, environment, TEST_TYPE_REGRESSION, null);
                caps.setCapability(AndroidMobileCapabilityType.AVD, avds[i]);
                caps.setCapability(MobileCapabilityType.DEVICE_NAME, avds[i]);
                caps.setCapability(AndroidMobileCapabilityType.SYSTEM_PORT, 8200 + i);

                allCaps.put("Android_Device_" + (i + 1), caps);
            }

        } else if (PLATFORM_IOS.equalsIgnoreCase(platform)) {
            // For iOS: Use different WDA ports
            String[] simulators = getAvailableSimulators();

            for (int i = 0; i < Math.min(deviceCount, simulators.length); i++) {
                DesiredCapabilities caps = getCapabilities(platform, environment, TEST_TYPE_REGRESSION, null);
                caps.setCapability(MobileCapabilityType.DEVICE_NAME, simulators[i]);
                caps.setCapability(IOSMobileCapabilityType.WDA_LOCAL_PORT, 8100 + i);

                allCaps.put("iOS_Device_" + (i + 1), caps);
            }
        }

        return allCaps;
    }

    // Helper methods (implementations would read from configuration)
    private static Properties loadConfiguration() {
        // Load from properties file, environment variables, etc.
        Properties props = new Properties();
        // Implementation would read from config files
        return props;
    }

    private static void validateInputs(String platform, String environment, String testType) {
        if (!PLATFORM_ANDROID.equalsIgnoreCase(platform) && 
            !PLATFORM_IOS.equalsIgnoreCase(platform)) {
            throw new IllegalArgumentException("Unsupported platform: " + platform);
        }

        // Additional validation logic here
    }

    private static void applyOverrides(DesiredCapabilities caps, Map<String, Object> overrides) {
        for (Map.Entry<String, Object> entry : overrides.entrySet()) {
            caps.setCapability(entry.getKey(), entry.getValue());
        }
    }

    private static void validateCapabilities(DesiredCapabilities caps) {
        // Check required capabilities
        if (!caps.asMap().containsKey(MobileCapabilityType.PLATFORM_NAME)) {
            throw new IllegalStateException("Missing required capability: platformName");
        }

        if (!caps.asMap().containsKey(MobileCapabilityType.AUTOMATION_NAME)) {
            throw new IllegalStateException("Missing required capability: automationName");
        }

        // Platform-specific validation
        String platform = (String) caps.getCapability(MobileCapabilityType.PLATFORM_NAME);

        if ("Android".equalsIgnoreCase(platform)) {
            // Android specific validation
            if (!caps.asMap().containsKey(MobileCapabilityType.DEVICE_NAME) &&
                !caps.asMap().containsKey(MobileCapabilityType.UDID)) {
                throw new IllegalStateException("Android requires either deviceName or udid");
            }

        } else if ("iOS".equalsIgnoreCase(platform)) {
            // iOS specific validation
            if (!caps.asMap().containsKey(MobileCapabilityType.DEVICE_NAME) &&
                !caps.asMap().containsKey(MobileCapabilityType.UDID)) {
                throw new IllegalStateException("iOS requires either deviceName or udid");
            }
        }
    }

    private static String getAppPathForEnvironment(String platform, String environment) {
        // Implementation would return different app paths based on environment
        // This is where you'd integrate with your build system or artifact repository
        return null;
    }

    private static String[] getAvailableAvds() {
        // Implementation would list available Android Virtual Devices
        return new String[]{"Pixel_6_API_33", "Pixel_4_API_30", "Nexus_5_API_28"};
    }

    private static String[] getAvailableSimulators() {
        // Implementation would list available iOS simulators
        return new String[]{"iPhone 14", "iPhone 14 Pro", "iPhone 13"};
    }
}

import io.appium.java_client.AppiumDriver;
import io.appium.java_client.android.AndroidDriver;
import io.appium.java_client.ios.IOSDriver;
import org.openqa.selenium.By;
import org.openqa.selenium.WebElement;
import org.openqa.selenium.remote.DesiredCapabilities;
import org.testng.annotations.AfterClass;
import org.testng.annotations.BeforeClass;
import org.testng.annotations.Test;

import java.net.URL;
import java.time.Duration;

public class FirstAppiumTest {

    private AppiumDriver driver;

    @BeforeClass
    public void setUp() throws Exception {
        // Configure desired capabilities
        DesiredCapabilities caps = new DesiredCapabilities();

        // Common capabilities for both platforms
        caps.setCapability("platformName", "Android"); // or "iOS"
        caps.setCapability("deviceName", "Pixel_6_Pro_API_33");
        caps.setCapability("automationName", "UiAutomator2"); // "XCUITest" for iOS

        // Application under test
        caps.setCapability("appPackage", "com.android.calculator2");
        caps.setCapability("appActivity", "com.android.calculator2.Calculator");

        // Optional: App path if not pre-installed
        // caps.setCapability("app", "/path/to/app.apk");

        // Optional: Reset behavior
        caps.setCapability("noReset", true);
        caps.setCapability("fullReset", false);

        // Initialize driver
        URL appiumServerUrl = new URL("http://127.0.0.1:4723");

        // Platform-specific driver initialization
        String platform = caps.getCapability("platformName").toString();
        if (platform.equalsIgnoreCase("Android")) {
            driver = new AndroidDriver(appiumServerUrl, caps);
        } else if (platform.equalsIgnoreCase("iOS")) {
            driver = new IOSDriver(appiumServerUrl, caps);
        }

        // Configure implicit wait
        driver.manage().timeouts().implicitlyWait(Duration.ofSeconds(10));
    }

    @Test
    public void testBasicCalculatorOperations() {
        // Test addition: 5 + 3 = 8

        // Locate number buttons
        WebElement digit5 = driver.findElement(By.id("com.android.calculator2:id/digit_5"));
        WebElement digit3 = driver.findElement(By.id("com.android.calculator2:id/digit_3"));
        WebElement plusBtn = driver.findElement(By.id("com.android.calculator2:id/op_add"));
        WebElement equalsBtn = driver.findElement(By.id("com.android.calculator2:id/eq"));
        WebElement resultField = driver.findElement(By.id("com.android.calculator2:id/result"));

        // Perform calculation
        digit5.click();
        plusBtn.click();
        digit3.click();
        equalsBtn.click();

        // Verify result
        String result = resultField.getText();
        assert result.equals("8") : "Expected 8 but got " + result;

        System.out.println("Test passed: 5 + 3 = " + result);
    }

    @Test
    public void testClearFunctionality() {
        // Test clear button functionality
        WebElement clearBtn = driver.findElement(By.id("com.android.calculator2:id/clr"));
        WebElement resultField = driver.findElement(By.id("com.android.calculator2:id/result"));

        // Enter some numbers
        driver.findElement(By.id("com.android.calculator2:id/digit_9")).click();
        driver.findElement(By.id("com.android.calculator2:id/digit_9")).click();

        // Clear the display
        clearBtn.click();

        // Verify display is cleared
        String result = resultField.getText();
        assert result.isEmpty() || result.equals("0") : "Display not cleared properly";

        System.out.println("Test passed: Clear functionality works");
    }

    @AfterClass
    public void tearDown() {
        if (driver != null) {
            // Take screenshot before closing (optional)
            // File screenshot = ((TakesScreenshot)driver).getScreenshotAs(OutputType.FILE);

            // Quit driver and close session
            driver.quit();
            System.out.println("Test completed and driver closed");
        }
    }
}

package com.mobileautomation.waits;

import io.appium.java_client.AppiumDriver;
import org.openqa.selenium.*;
import org.openqa.selenium.support.ui.*;
import java.time.Duration;
import java.util.List;
import java.util.function.Function;

public class AdvancedWaitStrategies {

    private final AppiumDriver driver;
    private WebDriverWait defaultWait;

    public AdvancedWaitStrategies(AppiumDriver driver) {
        this.driver = driver;
        // Configure default explicit wait
        this.defaultWait = new WebDriverWait(driver, Duration.ofSeconds(15));

        // Configure implicit wait (global timeout for element finding)
        driver.manage().timeouts().implicitlyWait(Duration.ofSeconds(5));
    }

    /**
     * Wait for element to be visible and clickable
     */
    public WebElement waitForElementClickable(By locator) {
        return defaultWait.until(
            ExpectedConditions.elementToBeClickable(locator)
        );
    }

    /**
     * Wait for element to be visible
     */
    public WebElement waitForElementVisible(By locator) {
        return defaultWait.until(
            ExpectedConditions.visibilityOfElementLocated(locator)
        );
    }

    /**
     * Wait for element to disappear
     */
    public boolean waitForElementInvisible(By locator) {
        return defaultWait.until(
            ExpectedConditions.invisibilityOfElementLocated(locator)
        );
    }

    /**
     * Wait for element to contain specific text
     */
    public WebElement waitForElementWithText(By locator, String expectedText) {
        return defaultWait.until(
            ExpectedConditions.textToBe(locator, expectedText)
        );
    }

    /**
     * Wait for element to contain partial text
     */
    public WebElement waitForElementWithPartialText(By locator, String partialText) {
        return defaultWait.until(
            driver -> {
                WebElement element = driver.findElement(locator);
                String actualText = element.getText();
                return actualText.contains(partialText) ? element : null;
            }
        );
    }

    /**
     * Wait for element attribute to have specific value
     */
    public WebElement waitForElementAttribute(By locator, String attribute, String expectedValue) {
        return defaultWait.until(
            driver -> {
                WebElement element = driver.findElement(locator);
                String actualValue = element.getAttribute(attribute);
                return expectedValue.equals(actualValue) ? element : null;
            }
        );
    }

    /**
     * Wait for alert to be present
     */
    public Alert waitForAlert() {
        return defaultWait.until(
            ExpectedConditions.alertIsPresent()
        );
    }

    /**
     * Wait for activity to change (Android specific)
     */
    public void waitForActivity(String expectedActivity, int timeoutSeconds) {
        WebDriverWait activityWait = new WebDriverWait(driver, Duration.ofSeconds(timeoutSeconds));
        activityWait.until(
            driver -> {
                if (driver instanceof AndroidDriver) {
                    String currentActivity = ((AndroidDriver) driver).currentActivity();
                    return currentActivity.contains(expectedActivity);
                }
                return false;
            }
        );
    }

    /**
     * Wait for network idle (custom condition)
     */
    public void waitForNetworkIdle(int maxWaitSeconds) {
        WebDriverWait networkWait = new WebDriverWait(driver, Duration.ofSeconds(maxWaitSeconds));
        networkWait.until(
            driver -> {
                // Check for loading indicators
                List<WebElement> loadingIndicators = driver.findElements(
                    By.xpath("//*[contains(@text, 'Loading') or contains(@text, 'Please wait')]")
                );

                // Check for progress bars
                List<WebElement> progressBars = driver.findElements(
                    By.className("android.widget.ProgressBar")
                );

                // Network is idle if no loading indicators or progress bars are visible
                return loadingIndicators.isEmpty() && progressBars.isEmpty();
            }
        );
    }

    /**
     * Fluent wait with custom polling interval
     */
    public WebElement fluentWaitForElement(By locator, int timeoutSeconds, int pollingIntervalMillis) {
        Wait<WebDriver> fluentWait = new FluentWait<>(driver)
            .withTimeout(Duration.ofSeconds(timeoutSeconds))
            .pollingEvery(Duration.ofMillis(pollingIntervalMillis))
            .ignoring(NoSuchElementException.class)
            .ignoring(StaleElementReferenceException.class);

        return fluentWait.until(
            driver -> {
                WebElement element = driver.findElement(locator);
                return element.isDisplayed() && element.isEnabled() ? element : null;
            }
        );
    }

    /**
     * Wait with retry mechanism
     */
    public WebElement waitWithRetry(By locator, int maxRetries) {
        WebElement element = null;
        Exception lastException = null;

        for (int attempt = 0; attempt < maxRetries; attempt++) {
            try {
                element = waitForElementVisible(locator);
                break;
            } catch (TimeoutException e) {
                lastException = e;
                System.out.printf("Attempt %d failed, retrying...\n", attempt + 1);

                // Optional: Add small delay between retries
                try {
                    Thread.sleep(500);
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                }
            }
        }

        if (element == null && lastException != null) {
            throw new RuntimeException("Element not found after " + maxRetries + " attempts", lastException);
        }

        return element;
    }

    /**
     * Custom wait for list to have minimum items
     */
    public List<WebElement> waitForMinimumListItems(By listLocator, int minItems) {
        return defaultWait.until(
            driver -> {
                List<WebElement> items = driver.findElements(listLocator);
                return items.size() >= minItems ? items : null;
            }
        );
    }

    /**
     * Smart wait that adapts based on platform
     */
    public WebElement smartWaitForElement(By locator) {
        String platform = driver.getCapabilities().getCapability("platformName").toString();

        if (platform.equalsIgnoreCase("Android")) {
            // Android specific wait conditions
            return waitForElementVisible(locator);
        } else if (platform.equalsIgnoreCase("iOS")) {
            // iOS may need longer waits for animations
            WebDriverWait iosWait = new WebDriverWait(driver, Duration.ofSeconds(20));
            return iosWait.until(
                ExpectedConditions.visibilityOfElementLocated(locator)
            );
        } else {
            return waitForElementVisible(locator);
        }
    }

    /**
     * Utility method to reset implicit wait
     */
    public void resetImplicitWait(int seconds) {
        driver.manage().timeouts().implicitlyWait(Duration.ofSeconds(seconds));
    }

    /**
     * Disable implicit wait (useful for checking element absence)
     */
    public void disableImplicitWait() {
        driver.manage().timeouts().implicitlyWait(Duration.ofSeconds(0));
    }

    /**
     * Restore default implicit wait
     */
    public void restoreImplicitWait() {
        driver.manage().timeouts().implicitlyWait(Duration.ofSeconds(5));
    }
}

from appium.webdriver.common.appiumby import AppiumBy
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
from selenium.common.exceptions import TimeoutException, NoSuchElementException
from selenium.webdriver.common.by import By
import time

class SmartWaits:
    """Comprehensive waiting strategies for Appium tests"""

    def __init__(self, driver, default_timeout=15):
        self.driver = driver
        self.default_timeout = default_timeout
        self.default_wait = WebDriverWait(driver, default_timeout)

        # Set implicit wait
        driver.implicitly_wait(5)

    def wait_for_element(self, locator, timeout=None):
        """Wait for element to be present"""
        wait = self.default_wait if timeout is None else WebDriverWait(self.driver, timeout)
        return wait.until(EC.presence_of_element_located(locator))

    def wait_for_visible(self, locator, timeout=None):
        """Wait for element to be visible"""
        wait = self.default_wait if timeout is None else WebDriverWait(self.driver, timeout)
        return wait.until(EC.visibility_of_element_located(locator))

    def wait_for_clickable(self, locator, timeout=None):
        """Wait for element to be clickable"""
        wait = self.default_wait if timeout is None else WebDriverWait(self.driver, timeout)
        return wait.until(EC.element_to_be_clickable(locator))

    def wait_for_invisible(self, locator, timeout=None):
        """Wait for element to disappear"""
        wait = self.default_wait if timeout is None else WebDriverWait(self.driver, timeout)
        return wait.until(EC.invisibility_of_element_located(locator))

    def wait_for_text(self, locator, expected_text, timeout=None):
        """Wait for element to contain specific text"""
        wait = self.default_wait if timeout is None else WebDriverWait(self.driver, timeout)
        return wait.until(EC.text_to_be_present_in_element(locator, expected_text))

    def wait_for_attribute(self, locator, attribute, expected_value, timeout=None):
        """Wait for element attribute to have specific value"""
        def attribute_condition(driver):
            try:
                element = driver.find_element(*locator)
                actual_value = element.get_attribute(attribute)
                return actual_value == expected_value
            except:
                return False

        wait = self.default_wait if timeout is None else WebDriverWait(self.driver, timeout)
        return wait.until(attribute_condition)

    def wait_for_activity(self, expected_activity, timeout=30):
        """Wait for specific activity (Android only)"""
        wait = WebDriverWait(self.driver, timeout)
        return wait.until(
            lambda driver: expected_activity in driver.current_activity
        )

    def wait_for_list_items(self, list_locator, min_items=1, timeout=None):
        """Wait for list to have minimum number of items"""
        def list_condition(driver):
            items = driver.find_elements(*list_locator)
            return len(items) >= min_items

        wait = self.default_wait if timeout is None else WebDriverWait(self.driver, timeout)
        return wait.until(list_condition)

    def wait_with_retry(self, locator, max_retries=3, delay=1):
        """Wait for element with retry mechanism"""
        for attempt in range(max_retries):
            try:
                return self.wait_for_visible(locator, timeout=5)
            except TimeoutException:
                if attempt < max_retries - 1:
                    print(f"Attempt {attempt + 1} failed, retrying in {delay} seconds...")
                    time.sleep(delay)
                else:
                    raise

    def is_element_present(self, locator, timeout=5):
        """Check if element is present without throwing exception"""
        try:
            self.wait_for_element(locator, timeout)
            return True
        except TimeoutException:
            return False

    def wait_for_network_idle(self, timeout=30, check_interval=1):
        """Wait for network activity to complete"""
        end_time = time.time() + timeout

        while time.time() < end_time:
            # Check for loading indicators
            loading_indicators = self.driver.find_elements(
                AppiumBy.ANDROID_UIAUTOMATOR,
                'new UiSelector().textContains("Loading")'
            )

            progress_bars = self.driver.find_elements(
                AppiumBy.CLASS_NAME, 'android.widget.ProgressBar'
            )

            if not loading_indicators and not progress_bars:
                return True

            time.sleep(check_interval)

        raise TimeoutException(f"Network not idle after {timeout} seconds")

    def disable_implicit_wait(self):
        """Temporarily disable implicit wait"""
        self.driver.implicitly_wait(0)

    def restore_implicit_wait(self):
        """Restore implicit wait to default"""
        self.driver.implicitly_wait(5)

# Usage example
def test_with_smart_waits(driver):
    waits = SmartWaits(driver)

    # Wait for login button to be clickable
    login_button = waits.wait_for_clickable(
        (AppiumBy.ACCESSIBILITY_ID, 'login_button')
    )
    login_button.click()

    # Wait for login form to appear
    waits.wait_for_visible(
        (AppiumBy.ID, 'com.app:id/login_form')
    )

    # Wait for specific text to appear
    waits.wait_for_text(
        (AppiumBy.ID, 'com.app:id/welcome_message'),
        'Welcome back'
    )

    # Check if element is present without failing test
    if waits.is_element_present((AppiumBy.ID, 'error_message'), timeout=2):
        print("Error message detected")

    # Wait with retry for flaky elements
    profile_image = waits.wait_with_retry(
        (AppiumBy.ID, 'profile_image'),
        max_retries=3
    )

import io.appium.java_client.AppiumBy;
import org.openqa.selenium.By;
import org.openqa.selenium.WebElement;
import org.openqa.selenium.support.ui.ExpectedConditions;
import org.openqa.selenium.support.ui.WebDriverWait;
import java.time.Duration;
import java.util.List;

public class SmartElementFinder {

    public WebElement findElementWithFallback(String elementId, String elementText) {
        // Priority 1: Accessibility ID (cross-platform)
        try {
            return new WebDriverWait(driver, Duration.ofSeconds(3))
                .until(ExpectedConditions.presenceOfElementLocated(
                    AppiumBy.accessibilityId(elementId)
                ));
        } catch (Exception e) {
            // Priority 2: Platform-specific strategies
            if (isAndroid()) {
                return findAndroidElement(elementId, elementText);
            } else {
                return findIOSElement(elementId, elementText);
            }
        }
    }

    private WebElement findAndroidElement(String elementId, String elementText) {
        List<By> androidLocators = List.of(
            AppiumBy.id("com.app:id/" + elementId),
            AppiumBy.androidUIAutomator(
                "new UiSelector().text(\"" + elementText + "\")"
            ),
            AppiumBy.androidUIAutomator(
                "new UiSelector().description(\"" + elementText + "\")"
            ),
            By.xpath("//*[@text='" + elementText + "']"),
            By.xpath("//*[contains(@text, '" + elementText + "')]"),
            By.xpath("//*[@content-desc='" + elementText + "']")
        );

        return findWithCascadingStrategy(androidLocators);
    }

    private WebElement findIOSElement(String elementId, String elementText) {
        List<By> iosLocators = List.of(
            AppiumBy.name(elementId),
            AppiumBy.iOSNsPredicateString(
                "label == '" + elementText + "'"
            ),
            AppiumBy.iOSNsPredicateString(
                "label CONTAINS '" + elementText + "'"
            ),
            AppiumBy.iOSClassChain(
                "**/*[`label == '" + elementText + "'`]"
            ),
            By.xpath("//*[@label='" + elementText + "']")
        );

        return findWithCascadingStrategy(iosLocators);
    }

    private WebElement findWithCascadingStrategy(List<By> locators) {
        for (By locator : locators) {
            try {
                return new WebDriverWait(driver, Duration.ofSeconds(2))
                    .until(ExpectedConditions.presenceOfElementLocated(locator));
            } catch (Exception e) {
                continue; // Try next locator
            }
        }
        throw new RuntimeException("Element not found with any locator strategy");
    }

    private boolean isAndroid() {
        return driver.getCapabilities().getCapability("platformName")
            .equals("Android");
    }
}

import org.openqa.selenium.interactions.Actions;
import org.openqa.selenium.interactions.PointerInput;
import org.openqa.selenium.interactions.Sequence;
import java.time.Duration;
import java.util.Collections;

public class ModernGestureController {

    // Using W3C Actions API (recommended for new code)
    public void performSwipe(int startX, int startY, int endX, int endY) {
        PointerInput finger = new PointerInput(PointerInput.Kind.TOUCH, "finger");
        Sequence swipe = new Sequence(finger, 0)
            .addAction(finger.createPointerMove(Duration.ZERO, 
                PointerInput.Origin.viewport(), startX, startY))
            .addAction(finger.createPointerDown(PointerInput.MouseButton.LEFT.asArg()))
            .addAction(new Pause(finger, Duration.ofMillis(100)))
            .addAction(finger.createPointerMove(Duration.ofMillis(500), 
                PointerInput.Origin.viewport(), endX, endY))
            .addAction(finger.createPointerUp(PointerInput.MouseButton.LEFT.asArg()));

        driver.perform(Collections.singletonList(swipe));
    }

    // Pinch-to-zoom with multi-touch
    public void pinchZoom(WebElement element, boolean zoomIn) {
        // Calculate element center
        Point center = getCenter(element);
        int offset = zoomIn ? 50 : 100;

        // First finger sequence
        PointerInput finger1 = new PointerInput(PointerInput.Kind.TOUCH, "finger1");
        Sequence seq1 = new Sequence(finger1, 0)
            .addAction(finger1.createPointerMove(Duration.ZERO, 
                PointerInput.Origin.viewport(), center.x - offset, center.y - offset))
            .addAction(finger1.createPointerDown(PointerInput.MouseButton.LEFT.asArg()))
            .addAction(new Pause(finger1, Duration.ofMillis(100)))
            .addAction(finger1.createPointerMove(Duration.ofMillis(500), 
                PointerInput.Origin.viewport(), 
                zoomIn ? center.x - offset * 2 : center.x - offset / 2, 
                zoomIn ? center.y - offset * 2 : center.y - offset / 2))
            .addAction(finger1.createPointerUp(PointerInput.MouseButton.LEFT.asArg()));

        // Second finger sequence
        PointerInput finger2 = new PointerInput(PointerInput.Kind.TOUCH, "finger2");
        Sequence seq2 = new Sequence(finger2, 1)
            .addAction(finger2.createPointerMove(Duration.ZERO, 
                PointerInput.Origin.viewport(), center.x + offset, center.y + offset))
            .addAction(finger2.createPointerDown(PointerInput.MouseButton.LEFT.asArg()))
            .addAction(new Pause(finger2, Duration.ofMillis(100)))
            .addAction(finger2.createPointerMove(Duration.ofMillis(500), 
                PointerInput.Origin.viewport(), 
                zoomIn ? center.x + offset * 2 : center.x + offset / 2, 
                zoomIn ? center.y + offset * 2 : center.y + offset / 2))
            .addAction(finger2.createPointerUp(PointerInput.MouseButton.LEFT.asArg()));

        // Execute both sequences simultaneously
        driver.perform(Arrays.asList(seq1, seq2));
    }

    // Scroll to element utility
    public void scrollToElement(String elementText) {
        // Android UIAutomator scroll
        if (isAndroid()) {
            driver.findElement(AppiumBy.androidUIAutomator(
                "new UiScrollable(new UiSelector().scrollable(true))" +
                ".scrollIntoView(new UiSelector().text(\"" + elementText + "\"))"
            ));
        } else {
            // iOS scroll using JavaScript
            JavascriptExecutor js = (JavascriptExecutor) driver;
            HashMap<String, String> scrollObject = new HashMap<>();
            scrollObject.put("direction", "down");
            scrollObject.put("predicateString", "label == '" + elementText + "'");
            js.executeScript("mobile: scroll", scrollObject);
        }
    }
}

