// Layer 5: Driver & Configuration
public abstract class BasePage {
    protected AppiumDriver driver;
    protected WebDriverWait wait;
    protected String platform;

    public BasePage(AppiumDriver driver) {
        this.driver = driver;
        this.wait = new WebDriverWait(driver, Duration.ofSeconds(15));
        this.platform = driver.getCapabilities().getCapability("platformName").toString();
        PageFactory.initElements(new AppiumFieldDecorator(driver), this);
    }

    // Common utility methods
    protected boolean isAndroid() {
        return platform.equalsIgnoreCase("Android");
    }

    protected boolean isIOS() {
        return platform.equalsIgnoreCase("iOS");
    }

    protected void waitForVisibility(WebElement element) {
        wait.until(ExpectedConditions.visibilityOf(element));
    }

    protected void waitForClickable(WebElement element) {
        wait.until(ExpectedConditions.elementToBeClickable(element));
    }

    protected void tap(WebElement element) {
        waitForClickable(element);
        element.click();
    }

    protected void enterText(WebElement element, String text) {
        waitForVisibility(element);
        element.clear();
        element.sendKeys(text);
    }

    protected String getText(WebElement element) {
        waitForVisibility(element);
        return element.getText();
    }

    protected boolean isDisplayed(WebElement element) {
        try {
            return element.isDisplayed();
        } catch (Exception e) {
            return false;
        }
    }

    // Platform-specific element location
    protected By getPlatformSpecificLocator(String androidId, String iosAccessibilityId) {
        if (isAndroid()) {
            return By.id(androidId);
        } else {
            return By.xpath("//*[@name='" + iosAccessibilityId + "' or @label='" + iosAccessibilityId + "' or @value='" + iosAccessibilityId + "']");
        }
    }
}

