// Layer 2: Page Factory with enhanced platform support
class PageFactoryManager {
    private static Map<Class<?>, Object> pageCache = new HashMap<>();

    @SuppressWarnings("unchecked")
    public static <T> T getPage(AppiumDriver driver, Class<T> pageClass) {
        if (!pageCache.containsKey(pageClass)) {
            try {
                T page = pageClass.getConstructor(AppiumDriver.class).newInstance(driver);
                pageCache.put(pageClass, page);
            } catch (Exception e) {
                throw new RuntimeException("Failed to create page instance: " + pageClass.getName(), e);
            }
        }
        return (T) pageCache.get(pageClass);
    }

    public static void clearCache() {
        pageCache.clear();
    }
}

