"""
Complete Page Object Model Implementation in Python
"""

from abc import ABC, abstractmethod
from typing import Dict, List, Optional
from appium.webdriver.common.appiumby import AppiumBy
from appium.webdriver.webdriver import WebDriver
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
from selenium.webdriver.remote.webelement import WebElement
from selenium.common.exceptions import TimeoutException, NoSuchElementException
import time

# Layer 5: Base Page & Utilities
class BasePage(ABC):
    """Base class for all page objects"""

    def __init__(self, driver: WebDriver, timeout: int = 15):
        self.driver = driver
        self.timeout = timeout
        self.wait = WebDriverWait(driver, timeout)
        self.platform = driver.capabilities.get('platformName', '').lower()

    @property
    def is_android(self) -> bool:
        return self.platform == 'android'

    @property
    def is_ios(self) -> bool:
        return self.platform == 'ios'

    def get_platform_locator(self, android_locator: tuple, ios_locator: tuple) -> tuple:
        """Get platform-specific locator"""
        return android_locator if self.is_android else ios_locator

    def wait_for_element(self, locator: tuple, timeout: Optional[int] = None) -> WebElement:
        """Wait for element to be present"""
        wait = self.wait if timeout is None else WebDriverWait(self.driver, timeout)
        return wait.until(EC.presence_of_element_located(locator))

    def wait_for_visible(self, locator: tuple, timeout: Optional[int] = None) -> WebElement:
        """Wait for element to be visible"""
        wait = self.wait if timeout is None else WebDriverWait(self.driver, timeout)
        return wait.until(EC.visibility_of_element_located(locator))

    def wait_for_clickable(self, locator: tuple, timeout: Optional[int] = None) -> WebElement:
        """Wait for element to be clickable"""
        wait = self.wait if timeout is None else WebDriverWait(self.driver, timeout)
        return wait.until(EC.element_to_be_clickable(locator))

    def tap(self, element: WebElement):
        """Tap on element"""
        element.click()

    def enter_text(self, element: WebElement, text: str):
        """Enter text into element"""
        element.clear()
        element.send_keys(text)

    def get_text(self, element: WebElement) -> str:
        """Get text from element"""
        return element.text

    def is_displayed(self, element: WebElement) -> bool:
        """Check if element is displayed"""
        try:
            return element.is_displayed()
        except:
            return False

# Layer 4: Component Objects
class MobileComponents:
    """Reusable mobile UI components"""

    @staticmethod
    class NavigationBar:
        def __init__(self, driver: WebDriver):
            self.driver = driver
            self.platform = driver.capabilities.get('platformName', '').lower()

            # Platform-specific locators
            if self.platform == 'android':
                self.back_button = (AppiumBy.ID, 'com.app:id/back_button')
                self.title = (AppiumBy.ID, 'com.app:id/toolbar_title')
                self.menu_button = (AppiumBy.ID, 'com.app:id/menu_button')
            else:
                self.back_button = (AppiumBy.ACCESSIBILITY_ID, 'Back')
                self.title = (AppiumBy.ACCESSIBILITY_ID, 'Screen Title')
                self.menu_button = (AppiumBy.ACCESSIBILITY_ID, 'Menu')

        def go_back(self):
            """Tap back button"""
            self.driver.find_element(*self.back_button).click()

        def get_title(self) -> str:
            """Get navigation bar title"""
            return self.driver.find_element(*self.title).text

        def open_menu(self):
            """Open navigation menu"""
            self.driver.find_element(*self.menu_button).click()

    @staticmethod
    class Button:
        def __init__(self, element: WebElement):
            self.element = element

        def tap(self):
            self.element.click()

        def is_enabled(self) -> bool:
            return self.element.is_enabled()

        def get_text(self) -> str:
            return self.element.text

    @staticmethod
    class TextInput:
        def __init__(self, element: WebElement):
            self.element = element

        def enter(self, text: str):
            self.element.clear()
            self.element.send_keys(text)

        def get_value(self) -> str:
            return self.element.text

        def clear(self):
            self.element.clear()

# Layer 3: Page Objects
class LoginPage(BasePage):
    """Login page object"""

    # Locator dictionaries for platform abstraction
    LOCATORS = {
        'android': {
            'email_field': (AppiumBy.ID, 'com.app:id/email_field'),
            'password_field': (AppiumBy.ID, 'com.app:id/password_field'),
            'login_button': (AppiumBy.ID, 'com.app:id/login_button'),
            'forgot_password': (AppiumBy.ID, 'com.app:id/forgot_password'),
            'error_message': (AppiumBy.ID, 'com.app:id/error_message'),
            'welcome_text': (AppiumBy.ID, 'com.app:id/welcome_text')
        },
        'ios': {
            'email_field': (AppiumBy.ACCESSIBILITY_ID, 'email_field'),
            'password_field': (AppiumBy.ACCESSIBILITY_ID, 'password_field'),
            'login_button': (AppiumBy.ACCESSIBILITY_ID, 'login_button'),
            'forgot_password': (AppiumBy.ACCESSIBILITY_ID, 'forgot_password'),
            'error_message': (AppiumBy.ACCESSIBILITY_ID, 'error_message'),
            'welcome_text': (AppiumBy.ACCESSIBILITY_ID, 'welcome_text')
        }
    }

    def __init__(self, driver: WebDriver):
        super().__init__(driver)
        self.locators = self.LOCATORS.get(self.platform, self.LOCATORS['android'])

    def enter_email(self, email: str):
        """Enter email into email field"""
        email_field = self.wait_for_visible(self.locators['email_field'])
        self.enter_text(email_field, email)

    def enter_password(self, password: str):
        """Enter password into password field"""
        password_field = self.wait_for_visible(self.locators['password_field'])
        self.enter_text(password_field, password)

    def tap_login(self):
        """Tap login button"""
        login_button = self.wait_for_clickable(self.locators['login_button'])
        self.tap(login_button)

    def login(self, email: str, password: str):
        """Complete login flow"""
        self.enter_email(email)
        self.enter_password(password)
        self.tap_login()

    def tap_forgot_password(self):
        """Tap forgot password link"""
        forgot_password = self.wait_for_clickable(self.locators['forgot_password'])
        self.tap(forgot_password)

    def is_error_message_displayed(self) -> bool:
        """Check if error message is displayed"""
        try:
            error_message = self.wait_for_visible(self.locators['error_message'], timeout=5)
            return self.is_displayed(error_message)
        except TimeoutException:
            return False

    def get_error_message(self) -> str:
        """Get error message text"""
        error_message = self.wait_for_visible(self.locators['error_message'])
        return self.get_text(error_message)

    def is_login_button_enabled(self) -> bool:
        """Check if login button is enabled"""
        login_button = self.wait_for_visible(self.locators['login_button'])
        return login_button.is_enabled()

    def get_welcome_text(self) -> str:
        """Get welcome text"""
        welcome_text = self.wait_for_visible(self.locators['welcome_text'])
        return self.get_text(welcome_text)

class HomePage(BasePage):
