        """Logout from the app"""
        logout_button = self.wait_for_clickable(self.locators['logout_button'])
        self.tap(logout_button)

        # Handle confirmation dialog
        if self.is_android:
            confirm_button = (AppiumBy.ID, 'android:id/button1')
        else:
