# Layer 2: Page Factory
class PageFactory:
    """Factory for managing page objects"""

    _instances = {}

    @classmethod
    def get_page(cls, driver: WebDriver, page_class):
        """Get or create page instance"""
        key = (page_class, id(driver))
        if key not in cls._instances:
            cls._instances[key] = page_class(driver)
        return cls._instances[key]

    @classmethod
    def clear_cache(cls):
        """Clear page cache"""
        cls._instances.clear()

