import androidx.test.ext.junit.runners.AndroidJUnit4
import androidx.test.filters.LargeTest
import com.example.app.MainActivity
import com.example.app.R
import com.example.app.idlingresource.CountingIdlingResource
import com.example.app.idlingresource.EspressoIdlingResource
import com.example.app.pages.LoginPage
import com.example.app.pages.ProductListPage
import com.example.app.utils.CustomMatchers
import com.example.app.utils.TestDataFactory
import org.hamcrest.Matchers
import org.junit.After
import org.junit.Before
import org.junit.Rule
import org.junit.Test
import org.junit.runner.RunWith

@RunWith(AndroidJUnit4::class)
@LargeTest
class EspressoComprehensiveTests {

    // Test data
    private lateinit var testUser: TestUser
    private lateinit var testProducts: List<Product>

    // Idling resources
    private val countingIdlingResource = CountingIdlingResource("Network Calls")

    // Page objects
    private lateinit var loginPage: LoginPage
    private lateinit var productListPage: ProductListPage

    @get:Rule
    val activityRule = activityScenarioRule<MainActivity>()

    @Before
    fun setUp() {
        // Initialize test data
        testUser = TestDataFactory.createValidUser()
        testProducts = TestDataFactory.generateProducts(50)

        // Register idling resources
        IdlingRegistry.getInstance().register(countingIdlingResource)
        IdlingRegistry.getInstance().register(EspressoIdlingResource.countingIdlingResource)

        // Initialize Intents for intent testing
        Intents.init()

        // Initialize page objects
        loginPage = LoginPage()
        productListPage = ProductListPage()

        // Disable animations for reliable tests
        TestUtils.disableAnimations(activityRule.scenario)
    }

    @After
    fun tearDown() {
        // Unregister idling resources
        IdlingRegistry.getInstance().unregister(countingIdlingResource)
        IdlingRegistry.getInstance().unregister(EspressoIdlingResource.countingIdlingResource)

        // Release Intents
        Intents.release()

        // Re-enable animations
        TestUtils.enableAnimations(activityRule.scenario)
    }

    @Test
    fun testSuccessfulLoginWithValidCredentials() {
        // Given: User is on login screen
        loginPage.verifyLoginScreenDisplayed()

        // When: User enters valid credentials and clicks login
        countingIdlingResource.increment()
        loginPage.enterEmail(testUser.email)
        loginPage.enterPassword(testUser.password)
        loginPage.clickLoginButton()

        // Simulate network delay
        Thread.sleep(1000)
        countingIdlingResource.decrement()

        // Then: User should be redirected to home screen
        productListPage.verifyProductListDisplayed()
        productListPage.verifyWelcomeMessage(testUser.name)
    }

    @Test
    fun testLoginWithInvalidCredentialsShowsError() {
        // Given: User is on login screen
        loginPage.verifyLoginScreenDisplayed()

        // When: User enters invalid credentials
        loginPage.enterEmail("invalid@example.com")
        loginPage.enterPassword("wrongpassword")
        loginPage.clickLoginButton()

        // Then: Error message should be displayed
        loginPage.verifyErrorMessageDisplayed("Invalid credentials")

        // And: Login button should be disabled
        loginPage.verifyLoginButtonDisabled()
    }

    @Test
    fun testRecyclerViewScrollAndItemSelection() {
        // Given: User is logged in and on product list
        performLogin()

        // When: User scrolls to item at position 25 and clicks it
        Espresso.onView(ViewMatchers.withId(R.id.productRecyclerView))
            .perform(
                RecyclerViewActions.scrollToPosition<RecyclerView.ViewHolder>(25)
            )
            .perform(
                RecyclerViewActions.actionOnItemAtPosition<RecyclerView.ViewHolder>(
                    25,
                    ViewActions.click()
                )
            )

        // Then: Product detail screen should open
        Espresso.onView(ViewMatchers.withId(R.id.productDetailContainer))
            .check(ViewAssertions.matches(ViewMatchers.isDisplayed()))
    }

    @Test
    fun testSearchFunctionality() {
        // Given: User is logged in and on product list
        performLogin()

        // When: User enters search query
        val searchQuery = "laptop"
        Espresso.onView(ViewMatchers.withId(R.id.searchView))
            .perform(ViewActions.click())

        Espresso.onView(ViewMatchers.withId(R.id.search_src_text))
            .perform(
                ViewActions.typeText(searchQuery),
                ViewActions.pressImeActionButton()
            )

        // Then: Search results should be displayed
        Espresso.onView(ViewMatchers.withId(R.id.searchResultsRecyclerView))
            .check(ViewAssertions.matches(ViewMatchers.isDisplayed()))

        // And: Results should contain search query
        Espresso.onView(
            Matchers.allOf(
                ViewMatchers.withId(R.id.productName),
                ViewMatchers.withText(Matchers.containsString(searchQuery))
            )
        ).check(ViewAssertions.matches(ViewMatchers.isDisplayed()))
    }

    @Test
    fun testCheckoutFlowWithIntentVerification() {
        // Given: User has added items to cart
        performLogin()
        addProductToCart()

        // When: User proceeds to checkout
        Espresso.onView(ViewMatchers.withId(R.id.cartButton))
            .perform(ViewActions.click())

        Espresso.onView(ViewMatchers.withId(R.id.checkoutButton))
            .perform(ViewActions.click())

        // Then: Payment activity should be launched with correct intent
        Intents.intended(
            Matchers.allOf(
                IntentMatchers.hasComponent(PaymentActivity::class.java.name),
                IntentMatchers.hasExtra("total_amount", 99.99),
                IntentMatchers.hasExtra("currency", "USD")
            )
        )
    }

    @Test
    fun testAccessibilityRequirements() {
        // Given: User is on login screen
        loginPage.verifyLoginScreenDisplayed()

        // Then: All interactive elements should have content descriptions
        Espresso.onView(ViewMatchers.withId(R.id.emailField))
            .check(ViewAssertions.matches(
                CustomMatchers.hasContentDescription()
            ))

        Espresso.onView(ViewMatchers.withId(R.id.passwordField))
            .check(ViewAssertions.matches(
                CustomMatchers.hasContentDescription()
            ))

        Espresso.onView(ViewMatchers.withId(R.id.loginButton))
            .check(ViewAssertions.matches(
                CustomMatchers.hasContentDescription()
            ))

        // And: Touch targets should be at least 48dp
        Espresso.onView(ViewMatchers.withId(R.id.loginButton))
            .check(ViewAssertions.matches(
                CustomMatchers.hasMinimumTouchTarget(48)
            ))
    }

    @Test
    fun testDarkModeCompatibility() {
        // Given: App is launched in dark mode
        activityRule.scenario.onActivity { activity ->
            TestUtils.enableDarkMode(activity)
        }

        // When: User performs login
        performLogin()

        // Then: UI should be properly visible in dark mode
        Espresso.onView(ViewMatchers.withId(R.id.productRecyclerView))
            .check(ViewAssertions.matches(
                CustomMatchers.hasSufficientContrastRatio(4.5)
            ))
    }

    @Test
    fun testPerformanceMetrics() {
        // Start performance monitoring
        val testName = "testLoginPerformance"
        val performanceMonitor = PerformanceMonitor(testName)

        performanceMonitor.startTrace("login_flow")

        // Perform login
        performLogin()

        performanceMonitor.stopTrace("login_flow")

        // Assert performance metrics
        val metrics = performanceMonitor.getMetrics()
        assert(metrics["login_flow_duration_ms"]!! < 2000) {
            "Login flow took ${metrics["login_flow_duration_ms"]}ms, expected < 2000ms"
        }

        // Record metrics for CI dashboard
        performanceMonitor.recordMetricsToCI()
    }

    // Helper methods
    private fun performLogin() {
        loginPage.enterEmail(testUser.email)
        loginPage.enterPassword(testUser.password)
        loginPage.clickLoginButton()
        productListPage.verifyProductListDisplayed()
    }

    private fun addProductToCart() {
        Espresso.onView(ViewMatchers.withId(R.id.productRecyclerView))
            .perform(
                RecyclerViewActions.actionOnItemAtPosition<RecyclerView.ViewHolder>(
                    0,
                    ViewActions.click()
                )
            )

        Espresso.onView(ViewMatchers.withId(R.id.addToCartButton))
            .perform(ViewActions.click())
    }
}

// Page Object Pattern Implementation
class LoginPage {

    fun verifyLoginScreenDisplayed() {
        Espresso.onView(ViewMatchers.withId(R.id.loginContainer))
            .check(ViewAssertions.matches(ViewMatchers.isDisplayed()))
    }

    fun enterEmail(email: String) {
        Espresso.onView(ViewMatchers.withId(R.id.emailField))
            .perform(
                ViewActions.typeText(email),
                ViewActions.closeSoftKeyboard()
            )
    }

    fun enterPassword(password: String) {
        Espresso.onView(ViewMatchers.withId(R.id.passwordField))
            .perform(
                ViewActions.typeText(password),
                ViewActions.closeSoftKeyboard()
            )
    }

    fun clickLoginButton() {
        Espresso.onView(ViewMatchers.withId(R.id.loginButton))
            .perform(ViewActions.click())
    }

    fun verifyErrorMessageDisplayed(expectedMessage: String) {
        Espresso.onView(ViewMatchers.withId(R.id.errorMessage))
            .check(ViewAssertions.matches(ViewMatchers.isDisplayed()))
            .check(ViewAssertions.matches(ViewMatchers.withText(expectedMessage)))
    }

    fun verifyLoginButtonDisabled() {
        Espresso.onView(ViewMatchers.withId(R.id.loginButton))
            .check(ViewAssertions.matches(Matchers.not(ViewMatchers.isEnabled())))
    }
}

// Custom Matchers
object CustomMatchers {

    fun hasContentDescription(): Matcher<View> {
        return object : BoundedMatcher<View, View>(View::class.java) {
            override fun describeTo(description: Description) {
                description.appendText("has content description")
            }

            override fun matchesSafely(view: View): Boolean {
                return view.contentDescription != null && 
                       view.contentDescription.toString().isNotEmpty()
            }
        }
    }

    fun hasMinimumTouchTarget(minSizeDp: Int): Matcher<View> {
        return object : BoundedMatcher<View, View>(View::class.java) {
            override fun describeTo(description: Description) {
                description.appendText("has minimum touch target of ${minSizeDp}dp")
            }

            override fun matchesSafely(view: View): Boolean {
                val displayMetrics = view.resources.displayMetrics
                val minSizePx = (minSizeDp * displayMetrics.density).toInt()

                return view.width >= minSizePx && view.height >= minSizePx
            }
        }
    }

    fun hasSufficientContrastRatio(minRatio: Double): Matcher<View> {
        return object : BoundedMatcher<View, View>(View::class.java) {
            override fun describeTo(description: Description) {
                description.appendText("has contrast ratio >= $minRatio")
            }

            override fun matchesSafely(view: View): Boolean {
                // Implement contrast ratio calculation
                // This is simplified - real implementation would calculate
                // foreground/background color contrast
                return true
            }
        }
    }
}

