import XCTest

class ShoppingAppUITests: XCTestCase {

    // MARK: - Properties

    var app: XCUIApplication!
    var springboard: XCUIApplication!

    // Test data
    let testUser = TestUser(
        email: "test@example.com",
        password: "password123",
        name: "Test User"
    )

    // Page objects
    var loginPage: LoginPage!
    var productListPage: ProductListPage!
    var cartPage: CartPage!

    // Performance metrics
    var performanceMetrics: [String: TimeInterval] = [:]

    // MARK: - Setup and Teardown

    override func setUp() {
        super.setUp()

        continueAfterFailure = false

        // Initialize applications
        app = XCUIApplication()
        springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")

        // Configure launch arguments
        app.launchArguments = [
            "--uitesting",
            "--reset-database",
            "-AppleLanguages", "(en)",
            "-AppleLocale", "en_US"
        ]

        // Configure environment variables
        app.launchEnvironment = [
            "TEST_MODE": "true",
            "DISABLE_ANIMATIONS": "true",
            "MOCK_NETWORK": "true"
        ]

        // Launch app
        app.launch()

        // Initialize page objects
        loginPage = LoginPage(app: app)
        productListPage = ProductListPage(app: app)
        cartPage = CartPage(app: app)

        // Handle initial system alerts
        handleInitialAlerts()
    }

    override func tearDown() {
        // Take screenshot on failure
        if let failureCount = testRun?.failureCount, failureCount > 0 {
            takeScreenshot(name: "FAILURE_\(name)")
        }

        // Log performance metrics
        if !performanceMetrics.isEmpty {
            logPerformanceMetrics()
        }

        // Terminate app
        app.terminate()

        super.tearDown()
    }

    // MARK: - Test Cases

    func testSuccessfulLoginFlow() {
        // Given: User is on login screen
        XCTAssertTrue(loginPage.isDisplayed(), "Login screen should be visible")

        // When: User enters valid credentials and taps login
        loginPage.enterEmail(testUser.email)
        loginPage.enterPassword(testUser.password)
        loginPage.tapLoginButton()

        // Then: User should be redirected to product list
        XCTAssertTrue(
            productListPage.waitForExistence(timeout: 5),
            "Product list should appear after login"
        )

        // And: Welcome message should display user name
        productListPage.verifyWelcomeMessage(contains: testUser.name)
    }

    func testLoginWithInvalidCredentials() {
        // Given: User is on login screen
        XCTAssertTrue(loginPage.isDisplayed())

        // When: User enters invalid credentials
        loginPage.enterEmail("invalid@example.com")
        loginPage.enterPassword("wrongpassword")
        loginPage.tapLoginButton()

        // Then: Error message should be displayed
        let errorMessage = app.staticTexts["error_message"]
        XCTAssertTrue(
            errorMessage.waitForExistence(timeout: 3),
            "Error message should appear"
        )
        XCTAssertEqual(
            errorMessage.label,
            "Invalid email or password",
            "Error message text should match"
        )

        // And: Login button should be disabled
        let loginButton = app.buttons["login_button"]
        XCTAssertFalse(loginButton.isEnabled, "Login button should be disabled after error")
    }

    func testProductSearchAndSelection() {
        // Given: User is logged in
        loginUser()

        // Start performance measurement
        let searchStartTime = Date()

        // When: User searches for a product
        productListPage.tapSearchField()
        productListPage.enterSearchQuery("iPhone")
        productListPage.tapSearchButton()

        // Record search performance
        let searchDuration = Date().timeIntervalSince(searchStartTime)
        performanceMetrics["search_duration"] = searchDuration

        // Then: Search results should be displayed
        let resultsTable = app.tables["search_results_table"]
        XCTAssertTrue(
            resultsTable.waitForExistence(timeout: 3),
            "Search results should appear"
        )

        // And: At least one result should contain search term
        let firstResult = resultsTable.cells.firstMatch
        XCTAssertTrue(firstResult.exists, "At least one search result should exist")

        // When: User taps first result
        firstResult.tap()

        // Then: Product detail screen should open
        let productDetailView = app.otherElements["product_detail_view"]
        XCTAssertTrue(
            productDetailView.waitForExistence(timeout: 3),
            "Product detail screen should open"
        )
    }

    func testTableScrollingAndDynamicContent() {
        // Given: User is logged in and on product list
        loginUser()

        let productTable = app.tables["products_table"]
        XCTAssertTrue(productTable.waitForExistence(timeout: 3))

        // When: User scrolls to bottom of table
        let startCell = productTable.cells.element(boundBy: 0)
        let lastCell = productTable.cells.element(boundBy: productTable.cells.count - 1)

        // Scroll until last cell is visible
        while !lastCell.isHittable {
            productTable.swipeUp()
        }

        // Then: Last cell should be visible and tappable
        XCTAssertTrue(lastCell.isHittable, "Last cell should be hittable after scrolling")

        // When: User taps last cell
        lastCell.tap()

        // Then: Product detail should open
        XCTAssertTrue(app.otherElements["product_detail_view"].waitForExistence(timeout: 3))
    }

    func testCheckoutFlowWithMultipleProducts() {
        // Given: User has added multiple products to cart
        loginUser()
        addProductsToCart(count: 3)

        // When: User navigates to cart and proceeds to checkout
        productListPage.tapCartButton()

        XCTAssertTrue(cartPage.isDisplayed(), "Cart screen should be visible")

        // Verify cart items
        let cartItems = app.tables["cart_items_table"].cells
        XCTAssertEqual(cartItems.count, 3, "Cart should contain 3 items")

        // Tap checkout button
        cartPage.tapCheckoutButton()

        // Then: Checkout screen should appear
        let checkoutScreen = app.otherElements["checkout_screen"]
        XCTAssertTrue(
            checkoutScreen.waitForExistence(timeout: 3),
            "Checkout screen should appear"
        )

        // When: User fills shipping information
        fillShippingInformation()

        // Then: Proceed to payment should be enabled
        let paymentButton = app.buttons["proceed_to_payment"]
        XCTAssertTrue(paymentButton.isEnabled, "Payment button should be enabled")
    }

    func testAccessibilityFeatures() {
        // Given: User is on login screen
        XCTAssertTrue(loginPage.isDisplayed())

        // Then: All interactive elements should have accessibility identifiers
        let emailField = app.textFields["email_field"]
        let passwordField = app.secureTextFields["password_field"]
        let loginButton = app.buttons["login_button"]

        XCTAssertTrue(emailField.exists, "Email field should exist")
        XCTAssertTrue(passwordField.exists, "Password field should exist")
        XCTAssertTrue(loginButton.exists, "Login button should exist")

        // And: Elements should have proper accessibility labels
        XCTAssertNotEqual(emailField.label, "", "Email field should have accessibility label")
        XCTAssertNotEqual(passwordField.label, "", "Password field should have accessibility label")

        // Test Dynamic Type support
        app.activate()
        // Note: Changing Dynamic Type requires system-level interaction
        // In real tests, this would be done via launch arguments or settings app
    }

    func testPerformanceAppLaunch() {
        // Measure app launch performance
        measure(metrics: [
            XCTApplicationLaunchMetric(),
            XCTCPUMetric(),
            XCTMemoryMetric()
        ]) {
            app.launch()
        }
    }

    func testDarkModeCompatibility() {
        // Given: App is launched in dark mode
        // Note: This requires launch argument or system setting
        // For demonstration, we'll just test UI elements adapt correctly

        loginUser()

        // Then: All text should be readable
        let allTextElements = app.staticTexts.allElementsBoundByIndex
        for textElement in allTextElements {
            if textElement.exists && textElement.isHittable {
                // In real implementation, check contrast ratio
                // This is simplified for example
                XCTAssertTrue(
                    textElement.frame.width > 0,
                    "Text element should have valid frame"
                )
            }
        }
    }

    // MARK: - Helper Methods

    private func loginUser() {
        if !productListPage.isDisplayed() {
            loginPage.enterEmail(testUser.email)
            loginPage.enterPassword(testUser.password)
            loginPage.tapLoginButton()
            XCTAssertTrue(
                productListPage.waitForExistence(timeout: 5),
                "Should be logged in and on product list"
            )
        }
    }

    private func addProductsToCart(count: Int) {
        let productTable = app.tables["products_table"]
        XCTAssertTrue(productTable.waitForExistence(timeout: 3))

        for i in 0..<min(count, productTable.cells.count) {
            let cell = productTable.cells.element(boundBy: i)
            cell.tap()

            // Add to cart from detail screen
            let addToCartButton = app.buttons["add_to_cart_button"]
            XCTAssertTrue(addToCartButton.waitForExistence(timeout: 2))
            addToCartButton.tap()

            // Go back to product list
            let backButton = app.buttons["Back"]
            if backButton.exists {
                backButton.tap()
            } else {
                app.swipeRight()
            }
        }
    }

    private func fillShippingInformation() {
        let nameField = app.textFields["shipping_name"]
        let addressField = app.textFields["shipping_address"]
        let cityField = app.textFields["shipping_city"]

        nameField.tap()
        nameField.typeText("John Doe")

        addressField.tap()
        addressField.typeText("123 Main St")

        cityField.tap()
        cityField.typeText("San Francisco")

        // Dismiss keyboard
        app.toolbars["Toolbar"].buttons["Done"].tap()
    }

    private func handleInitialAlerts() {
        // Handle any initial system alerts (permissions, etc.)
        let alert = springboard.alerts.firstMatch
        if alert.waitForExistence(timeout: 3) {
            // Look for common alert buttons
            let allowButton = alert.buttons["Allow"]
            let okButton = alert.buttons["OK"]
            let continueButton = alert.buttons["Continue"]

            if allowButton.exists {
                allowButton.tap()
            } else if okButton.exists {
                okButton.tap()
            } else if continueButton.exists {
                continueButton.tap()
            }
        }
    }

    private func takeScreenshot(name: String) {
        let screenshot = XCUIScreen.main.screenshot()
        let attachment = XCTAttachment(screenshot: screenshot)
        attachment.name = name
        attachment.lifetime = .keepAlways
        add(attachment)
    }

    private func logPerformanceMetrics() {
        print("\n=== Performance Metrics ===")
        for (metric, value) in performanceMetrics {
            print("\(metric): \(String(format: "%.2f", value))s")

            // Attach to test report
            let metricAttachment = XCTAttachment(string: "\(metric): \(value)")
            metricAttachment.name = "performance_\(metric)"
            metricAttachment.lifetime = .keepAlways
            add(metricAttachment)
        }
    }
}

