using NUnit.Framework;
using UnityEngine;
using UnityEngine.TestTools;
using System.Collections;
using System.Collections.Generic;
using UnityEngine.SceneManagement;

public class MobileGameTests
{
    // Game objects references
    private GameObject player;
    private GameObject gameManager;
    private UIManager uiManager;

    [UnitySetUp]
    public IEnumerator Setup()
    {
        // Load the game scene
        yield return SceneManager.LoadSceneAsync("GameScene", LoadSceneMode.Single);

        // Find game objects
        player = GameObject.FindWithTag("Player");
        gameManager = GameObject.Find("GameManager");
        uiManager = GameObject.Find("UIManager").GetComponent<UIManager>();

        Assert.IsNotNull(player, "Player should exist in scene");
        Assert.IsNotNull(gameManager, "GameManager should exist in scene");
        Assert.IsNotNull(uiManager, "UIManager should exist in scene");

        // Wait for game initialization
        yield return new WaitForSeconds(1f);
    }

    [UnityTest]
    public IEnumerator TestPlayerMovement()
    {
        // Get initial position
        Vector3 initialPosition = player.transform.position;

        // Simulate joystick input (right movement)
        InputSimulator.SimulateJoystick(JoystickAxis.Horizontal, 1f);

        // Wait for movement
        yield return new WaitForSeconds(0.5f);

        // Check if player moved
        Vector3 newPosition = player.transform.position;
        Assert.Greater(newPosition.x, initialPosition.x, "Player should move right");

        // Stop movement
        InputSimulator.SimulateJoystick(JoystickAxis.Horizontal, 0f);
    }

    [UnityTest]
    public IEnumerator TestEnemySpawnAndCombat()
    {
        // Get initial enemy count
        int initialEnemyCount = GameObject.FindGameObjectsWithTag("Enemy").Length;

        // Trigger enemy spawn
        SpawnManager spawnManager = gameManager.GetComponent<SpawnManager>();
        spawnManager.SpawnEnemyWave(1);

        // Wait for spawn
        yield return new WaitForSeconds(2f);

        // Check if enemy spawned
        int newEnemyCount = GameObject.FindGameObjectsWithTag("Enemy").Length;
        Assert.Greater(newEnemyCount, initialEnemyCount, "Enemy should spawn");

        // Get enemy reference
        GameObject enemy = GameObject.FindWithTag("Enemy");
        Assert.IsNotNull(enemy, "Enemy should exist");

        // Get player health before combat
        PlayerHealth playerHealth = player.GetComponent<PlayerHealth>();
        float initialHealth = playerHealth.currentHealth;

        // Simulate attack on enemy
        PlayerCombat playerCombat = player.GetComponent<PlayerCombat>();
        playerCombat.Attack(enemy.transform);

        // Wait for attack to complete
        yield return new WaitForSeconds(1f);

        // Check if enemy took damage or died
        EnemyHealth enemyHealth = enemy.GetComponent<EnemyHealth>();
        Assert.Less(enemyHealth.currentHealth, enemyHealth.maxHealth, "Enemy should take damage");
    }

    [UnityTest]
    public IEnumerator TestCollectibleCollection()
    {
        // Spawn a collectible
        CollectibleSpawner spawner = gameManager.GetComponent<CollectibleSpawner>();
        GameObject collectible = spawner.SpawnCollectible(CollectibleType.Coin);

        Assert.IsNotNull(collectible, "Collectible should spawn");

        // Get initial score
        ScoreManager scoreManager = gameManager.GetComponent<ScoreManager>();
        int initialScore = scoreManager.CurrentScore;

        // Move player to collectible
        Vector3 collectiblePosition = collectible.transform.position;
        player.transform.position = collectiblePosition;

        // Wait for collection
        yield return new WaitForSeconds(0.5f);

        // Check if collectible was collected
        Assert.IsFalse(collectible.activeInHierarchy, "Collectible should be collected");

        // Check if score increased
        int newScore = scoreManager.CurrentScore;
        Assert.Greater(newScore, initialScore, "Score should increase after collecting");
    }

    [UnityTest]
    public IEnumerator TestGamePauseAndResume()
    {
        // Ensure game is running
        Assert.IsFalse(Time.timeScale == 0f, "Game should be running initially");

        // Pause the game
        uiManager.PauseGame();

        yield return new WaitForSeconds(0.5f);

        // Check if game is paused
        Assert.IsTrue(Time.timeScale == 0f, "Game should be paused");
        Assert.IsTrue(uiManager.IsPauseMenuActive(), "Pause menu should be active");

        // Resume the game
        uiManager.ResumeGame();

        yield return new WaitForSeconds(0.5f);

        // Check if game resumed
        Assert.IsFalse(Time.timeScale == 0f, "Game should be running after resume");
        Assert.IsFalse(uiManager.IsPauseMenuActive(), "Pause menu should be hidden");
    }

    [UnityTest]
    public IEnumerator TestPerformanceFrameRate()
    {
        // Run performance test for 10 seconds
        float testDuration = 10f;
        float startTime = Time.time;

        List<float> frameTimes = new List<float>();
        List<float> frameRates = new List<float>();

        while (Time.time - startTime < testDuration)
        {
            // Record frame time
            float frameTime = Time.deltaTime;
            frameTimes.Add(frameTime);

            // Calculate frame rate
            float frameRate = 1f / frameTime;
            frameRates.Add(frameRate);

            // Ensure frame rate stays above minimum
            Assert.Greater(frameRate, 30f, "Frame rate should stay above 30 FPS");

            yield return null; // Wait for next frame
        }

        // Calculate statistics
        float avgFrameRate = CalculateAverage(frameRates);
        float minFrameRate = CalculateMin(frameRates);
        float frameTimeStdDev = CalculateStandardDeviation(frameTimes);

        // Log performance metrics
        Debug.Log($"Performance Test Results:");
        Debug.Log($"Average FPS: {avgFrameRate:F2}");
        Debug.Log($"Minimum FPS: {minFrameRate:F2}");
        Debug.Log($"Frame Time Std Dev: {frameTimeStdDev:F4}");

        // Assert performance requirements
        Assert.Greater(avgFrameRate, 45f, "Average FPS should be above 45");
        Assert.Greater(minFrameRate, 30f, "Minimum FPS should be above 30");
    }

    [UnityTest]
    public IEnumerator TestInAppPurchaseFlow()
    {
