    [UnityTest]
    public IEnumerator TestMultiTouchGestures()
    {
        // Test pinch zoom gesture
        Vector2 touch1Start = new Vector2(100, 300);
        Vector2 touch2Start = new Vector2(300, 300);

        // Simulate pinch (zoom out)
        InputSimulator.SimulateMultiTouch(
            new TouchEvent[] {
                new TouchEvent { phase = TouchPhase.Began, position = touch1Start },
                new TouchEvent { phase = TouchPhase.Began, position = touch2Start }
            }
        );

        yield return new WaitForSeconds(0.1f);

        // Move touches apart
        InputSimulator.SimulateMultiTouch(
            new TouchEvent[] {
                new TouchEvent { phase = TouchPhase.Moved, position = touch1Start - new Vector2(50, 0) },
                new TouchEvent { phase = TouchPhase.Moved, position = touch2Start + new Vector2(50, 0) }
            }
        );

        yield return new WaitForSeconds(0.1f);

        // Release touches
        InputSimulator.SimulateMultiTouch(
            new TouchEvent[] {
                new TouchEvent { phase = TouchPhase.Ended },
                new TouchEvent { phase = TouchPhase.Ended }
            }
        );

        // Verify camera zoomed out
        CameraController cameraController = Camera.main.GetComponent<CameraController>();
        Assert.Less(cameraController.ZoomLevel, 1f, "Camera should zoom out after pinch gesture");
    }

    // Helper methods
    private float CalculateAverage(List<float> values)
    {
        float sum = 0f;
        foreach (float value in values)
        {
            sum += value;
        }
        return sum / values.Count;
    }

    private float CalculateMin(List<float> values)
    {
        float min = float.MaxValue;
        foreach (float value in values)
        {
            if (value < min) min = value;
        }
        return min;
    }

    private float CalculateStandardDeviation(List<float> values)
    {
        float avg = CalculateAverage(values);
        float sumOfSquares = 0f;

        foreach (float value in values)
        {
            sumOfSquares += Mathf.Pow(value - avg, 2);
        }

        return Mathf.Sqrt(sumOfSquares / values.Count);
    }
}

