        public WearableTestResult testBatteryPerformance() {
            WearableTestResult result = new WearableTestResult("Battery Performance Test", true);

            try {
                // Get initial battery level
                double initialBattery = getBatteryLevel();
                result.addMetric("initial_battery_percent", initialBattery);

                // Start intensive operation (simulated)
                startIntensiveOperation();

                // Run for specified duration
                long testDurationMinutes = 5;
                long startTime = System.currentTimeMillis();

                List<Double> batteryReadings = new ArrayList<>();
                batteryReadings.add(initialBattery);

                while (System.currentTimeMillis() - startTime < (testDurationMinutes * 60 * 1000)) {
                    Thread.sleep(60000); // Check every minute
                    double currentBattery = getBatteryLevel();
                    batteryReadings.add(currentBattery);

                    System.out.println("Battery level: " + currentBattery + "%");
                }

                // Stop intensive operation
                stopIntensiveOperation();

                // Calculate battery drain rate
                double batteryDrain = initialBattery - batteryReadings.get(batteryReadings.size() - 1);
                double drainPerMinute = batteryDrain / testDurationMinutes;

                result.addMetric("final_battery_percent", batteryReadings.get(batteryReadings.size() - 1));
                result.addMetric("total_battery_drain_percent", batteryDrain);
                result.addMetric("battery_drain_per_minute", drainPerMinute);
                result.addMetric("test_duration_minutes", testDurationMinutes);

                // Check if drain is acceptable
                boolean acceptableDrain = drainPerMinute <= 2.0; // 2% per minute max
                result.addMetric("acceptable_drain", acceptableDrain);

                if (!acceptableDrain) {
                    System.out.println("Warning: High battery drain detected: " + drainPerMinute + "%/min");
