            tests.add(() -> testSmallScreenInteractions());
            tests.add(() -> testBatteryPerformance());

            // Execute tests
            ExecutorService executor = Executors.newFixedThreadPool(1); // Sequential for now

            try {
                for (Callable<WearableTestResult> test : tests) {
                    long startTime = System.currentTimeMillis();
                    WearableTestResult result = test.call();
                    long duration = System.currentTimeMillis() - startTime;

                    results.put(result, duration);

                    // Brief pause between tests
