"""Detect changed files and determine affected tests"""

import subprocess
import json
import os
from pathlib import Path

def get_changed_files():
    """Get files changed in current PR or push"""
    if os.getenv('GITHUB_EVENT_NAME') == 'pull_request':
        base_ref = os.getenv('GITHUB_BASE_REF', 'main')
        cmd = ['git', 'diff', '--name-only', f'origin/{base_ref}...HEAD']
    else:
        # For push events, get files changed in last commit
        cmd = ['git', 'diff', '--name-only', 'HEAD~1', 'HEAD']

    result = subprocess.run(cmd, capture_output=True, text=True)
    return result.stdout.strip().split('\n')

def map_files_to_tests(changed_files):
    """Map changed files to affected test files"""
    test_mapping = {
        # This would be populated from your codebase analysis
        'android/app/src/main/java/com/example/MainActivity.kt': [
            'android/app/src/test/java/com/example/MainActivityTest.kt',
            'android/app/src/androidTest/java/com/example/MainActivityUITest.kt'
        ],
        # Add more mappings
    }

    affected_tests = set()
    for file in changed_files:
        if file in test_mapping:
            affected_tests.update(test_mapping[file])

    return list(affected_tests)

def should_run_full_suite():
    """Determine if we should run full test suite"""
    changed_files = get_changed_files()

    # Run full suite if:
    # 1. Many files changed
    if len(changed_files) > 20:
        return True

    # 2. Build configuration files changed
    config_files = ['build.gradle', 'Podfile', 'package.json']
    if any(any(cf in f for cf in config_files) for f in changed_files):
        return True

    # 3. It's a scheduled run (nightly)
    if os.getenv('GITHUB_EVENT_NAME') == 'schedule':
        return True

    return False

if __name__ == '__main__':
    if should_run_full_suite():
        print('full')
    else:
        tests = map_files_to_tests(get_changed_files())
        print(json.dumps(tests))

