// Frame rate monitoring
import { useFrameCallback } from 'react-native-reanimated';

const FrameMonitor = () => {
  const [frameTimes, setFrameTimes] = useState([]);

  useFrameCallback((frameInfo) => {
    const { timestamp, timeSincePreviousFrame } = frameInfo;

    // Track frame times for jank detection
    setFrameTimes(prev => {
      const newTimes = [...prev, timeSincePreviousFrame];
      if (newTimes.length > 60) { // Keep last second
        newTimes.shift();
      }
      return newTimes;
    });

    // Detect jank (frame > 16.67ms for 60fps)
    if (timeSincePreviousFrame > 16.67) {
      Analytics.logEvent('jank_detected', {
        duration: timeSincePreviousFrame,
        timestamp: timestamp,
      });
    }
  });

  return null; // This is just a monitor component
};

