      // Set locale for test
      await this.setLocale(locale);

      // Run test
      try {
        await testFunction(locale);
        results[locale] = { status: 'passed' };
      } catch (error) {
        results[locale] = { 
          status: 'failed', 
          error: error.message 
        };
      }
    }

    return results;
  }

