    };

    history.totalRuns++;
    if (passed) {
      history.passes++;
    } else {
      history.failures++;
    }
    history.durations.push(duration);

    // Keep only last 100 runs
    if (history.durations.length > 100) {
      history.durations.shift();
    }

    this.testHistory.set(key, history);

    return this.calculateStability(history);
  }

  calculateStability(history) {
    if (history.totalRuns === 0) return 1.0;

    const passRate = history.passes / history.totalRuns;
    const durationVariance = this.calculateVariance(history.durations);

    // Stability score: pass rate weighted by duration consistency
    const stability = passRate * (1 - Math.min(durationVariance, 0.5));

    return {
      stability,
      isFlaky: stability < (1 - this.flakyThreshold),
      passRate,
      totalRuns: history.totalRuns,
    };
  }

  getFlakyTests() {
    const flakyTests = [];

    for (const [key, history] of this.testHistory.entries()) {
      const stability = this.calculateStability(history);
      if (stability.isFlaky) {
        flakyTests.push({
          test: key.split('-')[0],
          platform: history.platform,
          stability: stability.stability,
          passRate: stability.passRate,
          totalRuns: stability.totalRuns,
        });
      }
    }

    return flakyTests.sort((a, b) => a.stability - b.stability);
  }

  // Smart retry configuration based on test stability
  getRetryConfig(testName, platform) {
    const key = `${testName}-${platform}`;
    const history = this.testHistory.get(key);

    if (!history) {
      return { retries: 1, delay: 1000 }; // Default
    }

    const stability = this.calculateStability(history);

    if (stability.stability < 0.5) {
      // Very flaky: more retries, longer delays
      return { retries: 3, delay: 2000 };
    } else if (stability.stability < 0.8) {
      // Somewhat flaky
      return { retries: 2, delay: 1500 };
    } else {
      // Stable
      return { retries: 0, delay: 0 };
    }
  }
}

// Usage in test framework
const stabilityTracker = new TestStabilityTracker();

// Wrap test execution with tracking
async function runTestWithTracking(testName, platform, testFn) {
  const retryConfig = stabilityTracker.getRetryConfig(testName, platform);
  let lastError;

  for (let attempt = 0; attempt <= retryConfig.retries; attempt++) {
    if (attempt > 0) {
      console.log(`Retry ${attempt} for ${testName} on ${platform}`);
      await new Promise(resolve => setTimeout(resolve, retryConfig.delay));
    }

    const startTime = Date.now();
    try {
      await testFn();
      const duration = Date.now() - startTime;

      stabilityTracker.recordTestResult(testName, platform, true, duration);
      return { passed: true, attempts: attempt + 1 };
    } catch (error) {
      lastError = error;
      const duration = Date.now() - startTime;

      if (attempt === retryConfig.retries) {
        // Final attempt failed
        stabilityTracker.recordTestResult(testName, platform, false, duration);
        throw error;
      }
    }
  }
}

