// Main test function
export default function (data) {
  const user = data.testUsers[__VU % data.testUsers.length];

  // Group related requests for better reporting
  group('Authentication Flow', () => {
    // 1. Login
    const loginRes = http.post(
      'https://api.example.com/auth/login',
      JSON.stringify({
        email: user.email,
        password: user.password,
      }),
      {
        headers: { 'Content-Type': 'application/json' },
      }
    );

    // Track metrics
    responseTimeTrend.add(loginRes.timings.duration);
    requestCounter.add(1);

    // Check response
    const loginCheck = check(loginRes, {
      'login status is 200': (r) => r.status === 200,
      'login has token': (r) => r.json('token') !== undefined,
    });

    // Track errors
    if (!loginCheck) {
      errorRate.add(1);
    }

    const authToken = loginRes.json('token');

    // 2. Get user profile (authenticated)
    const profileRes = http.get(
      'https://api.example.com/users/me',
      {
        headers: {
          'Authorization': `Bearer ${authToken}`,
        },
      }
    );

    check(profileRes, {
      'profile status is 200': (r) => r.status === 200,
      'profile has email': (r) => r.json('email') === user.email,
    });

    // Small think time
    sleep(Math.random() * 2 + 1);
  });

  group('Product Browsing', () => {
    // 3. Browse products
    const productsRes = http.get('https://api.example.com/products');

    check(productsRes, {
      'products status is 200': (r) => r.status === 200,
      'products returned': (r) => r.json().length > 0,
    });

    // 4. Get specific product
    const productId = productsRes.json()[0].id;
    const productRes = http.get(`https://api.example.com/products/${productId}`);

    check(productRes, {
      'product status is 200': (r) => r.status === 200,
      'product has details': (r) => r.json('name') !== undefined,
