// ===== BASIC REQUEST SPECIFICATION =====
public class ApiSpecifications {

    // Singleton pattern for shared specs
    private static RequestSpecification defaultSpec;
    private static RequestSpecification adminSpec;
    private static RequestSpecification publicSpec;

    public static synchronized RequestSpecification getDefaultSpec() {
        if (defaultSpec == null) {
            defaultSpec = new RequestSpecBuilder()
                .setBaseUri(System.getProperty("api.base.url", "https://api.example.com"))
                .setBasePath("/v1")
                .setContentType(ContentType.JSON)
                .setAccept(ContentType.JSON)
                .addHeader("X-Request-ID", () -> UUID.randomUUID().toString())  // Lazy evaluation
                .addHeader("User-Agent", "REST-Assured-Tests/1.0")
                .addFilter(new RequestLoggingFilter(LogDetail.HEADERS))
                .addFilter(new ResponseLoggingFilter(LogDetail.STATUS))
                .build();
        }
        return defaultSpec;
    }

    public static synchronized RequestSpecification getAdminSpec() {
        if (adminSpec == null) {
            adminSpec = new RequestSpecBuilder()
                .addRequestSpecification(getDefaultSpec())
                .addHeader("X-API-Key", System.getenv("ADMIN_API_KEY"))
                .addFilter(new AllureRestAssured())
                .build();
        }
        return adminSpec;
    }

    public static synchronized RequestSpecification getPublicSpec() {
        if (publicSpec == null) {
            publicSpec = new RequestSpecBuilder()
                .addRequestSpecification(getDefaultSpec())
                .setBasePath("/public")
                .addQueryParam("api_key", System.getenv("PUBLIC_API_KEY"))
                .build();
        }
        return publicSpec;
    }

    // Dynamic specification with authentication
    public static RequestSpecification getAuthenticatedSpec(String token) {
        return new RequestSpecBuilder()
            .addRequestSpecification(getDefaultSpec())
            .addHeader("Authorization", "Bearer " + token)
            .build();
    }
}

