public static RequestSpecification getPerformanceSpec() {
    return new RequestSpecBuilder()
        .setConfig(RestAssured.config()
            .httpClient(HttpClientConfig.httpClientConfig()
                .setParam("http.connection.timeout", 10000)
                .setParam("http.socket.timeout", 10000)
                .setParam("http.connection-manager.timeout", 10000)))
        .addFilter((requestSpec, responseSpec, ctx) -> {
            long startTime = System.currentTimeMillis();
            Response response = ctx.next(requestSpec, responseSpec);
            long duration = System.currentTimeMillis() - startTime;

            // Log or assert on response time
            System.out.println("Request took: " + duration + "ms");

            if (duration > 5000) {
                System.err.println("WARNING: Slow response detected!");
            }

            return response;
        })
        .build();
}

