// ===== BEARER TOKEN AUTHENTICATION =====
public class TokenManager {

    private static String cachedToken;
    private static long tokenExpiryTime;

    public static synchronized String getAccessToken() {
        if (cachedToken == null || System.currentTimeMillis() > tokenExpiryTime) {
            refreshToken();
        }
        return cachedToken;
    }

    private static void refreshToken() {
        Response response = given()
            .auth().preemptive().basic(
                System.getenv("CLIENT_ID"), 
                System.getenv("CLIENT_SECRET")
            )
            .param("grant_type", "client_credentials")
        .when()
            .post("/oauth/token")
        .then()
            .statusCode(200)
            .extract()
            .response();

        cachedToken = response.jsonPath().getString("access_token");
        int expiresIn = response.jsonPath().getInt("expires_in");
        tokenExpiryTime = System.currentTimeMillis() + (expiresIn * 1000) - 60000; // 1 minute buffer
    }
}

