import io.restassured.http.ContentType;
import org.junit.jupiter.api.Test;
import java.util.HashMap;
import java.util.Map;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.*;

public class GraphQLTests {

    private static final String GRAPHQL_ENDPOINT = "/graphql";

    // Utility method to build GraphQL request
    private Map<String, Object> buildGraphQLRequest(String query, Map<String, Object> variables) {
        Map<String, Object> request = new HashMap<>();
        request.put("query", query);
        if (variables != null && !variables.isEmpty()) {
            request.put("variables", variables);
        }
        return request;
    }

    @Test
    public void testBasicGraphQLQuery() {
        String graphqlQuery = """
            query GetUser($userId: ID!) {
              user(id: $userId) {
                id
                name
                email
                posts {
                  id
                  title
                }
              }
            }
            """;

        Map<String, Object> variables = Map.of("userId", 123);
        Map<String, Object> requestBody = buildGraphQLRequest(graphqlQuery, variables);

        given()
            .contentType(ContentType.JSON)
            .body(requestBody)
        .when()
            .post(GRAPHQL_ENDPOINT)
        .then()
            .statusCode(200)
            .body("data.user.id", equalTo(123))
            .body("data.user.name", notNullValue())
            .body("data.user.email", matchesPattern(".+@.+\\..+"))
            .body("data.user.posts", hasSize(greaterThan(0)));
    }

    @Test
    public void testGraphQLErrorHandling() {
        String invalidQuery = """
            query {
              user(id: "invalid") {
                id
                name
                invalidField
              }
            }
            """;

        given()
            .contentType(ContentType.JSON)
            .body(buildGraphQLRequest(invalidQuery, null))
        .when()
            .post(GRAPHQL_ENDPOINT)
        .then()
            .statusCode(200) // GraphQL typically returns 200 even for errors
            .body("errors", notNullValue())
            .body("errors[0].message", containsString("invalidField"))
            .body("errors[0].locations", not(empty()))
            .body("errors[0].path", not(empty()));
    }

    @Test
    public void testGraphQLMutation() {
        String mutation = """
            mutation CreatePost($input: CreatePostInput!) {
              createPost(input: $input) {
                id
                title
                content
                author {
                  id
                  name
                }
              }
            }
            """;

        Map<String, Object> input = Map.of(
            "title", "Test Post",
            "content", "This is a test post",
            "authorId", 123
        );

        Map<String, Object> variables = Map.of("input", input);

        given()
            .contentType(ContentType.JSON)
            .body(buildGraphQLRequest(mutation, variables))
        .when()
            .post(GRAPHQL_ENDPOINT)
        .then()
            .statusCode(200)
            .body("data.createPost.id", notNullValue())
            .body("data.createPost.title", equalTo("Test Post"))
            .body("data.createPost.author.id", equalTo(123));
    }

    @Test
    public void testQueryComplexityLimiting() {
        // Try to query deeply nested data
        String complexQuery = """
            query {
              users(first: 10) {
                edges {
                  node {
                    id
                    posts(first: 10) {
                      edges {
                        node {
                          id
                          comments(first: 10) {
                            edges {
                              node {
                                id
                                author {
                                  id
                                  posts(first: 10) {
                                    edges {
                                      node {
                                        id
                                        # Deep nesting continues...
                                      }
                                    }
                                  }
                                }
                              }
                            }
                          }
                        }
                      }
                    }
                  }
                }
              }
            }
            """;

        given()
            .contentType(ContentType.JSON)
            .body(buildGraphQLRequest(complexQuery, null))
        .when()
            .post(GRAPHQL_ENDPOINT)
        .then()
            .statusCode(200)
            .body("errors", not(empty()))
            .body("errors[0].message", containsStringIgnoringCase("complexity"));
    }

    @Test
    public void testAuthenticationAndAuthorization() {
        String adminQuery = """
            query {
              adminStats {
                totalUsers
                activeUsers
                revenue
              }
            }
            """;

        // Test without authentication
        given()
            .contentType(ContentType.JSON)
            .body(buildGraphQLRequest(adminQuery, null))
        .when()
            .post(GRAPHQL_ENDPOINT)
        .then()
            .statusCode(200)
            .body("errors", not(empty()))
            .body("errors[0].message", containsStringIgnoringCase("authenticate"));

        // Test with regular user token
        given()
            .contentType(ContentType.JSON)
            .header("Authorization", "Bearer user-token")
            .body(buildGraphQLRequest(adminQuery, null))
        .when()
            .post(GRAPHQL_ENDPOINT)
        .then()
            .statusCode(200)
            .body("errors", not(empty()))
            .body("errors[0].message", containsStringIgnoringCase("permission"));

        // Test with admin token
        given()
            .contentType(ContentType.JSON)
            .header("Authorization", "Bearer admin-token")
            .body(buildGraphQLRequest(adminQuery, null))
        .when()
            .post(GRAPHQL_ENDPOINT)
        .then()
            .statusCode(200)
            .body("errors", nullValue())
            .body("data.adminStats", notNullValue());
    }

    @Test
    public void testIntrospectionQuery() {
        String introspectionQuery = """
            query IntrospectionQuery {
              __schema {
                queryType { name }
                mutationType { name }
                subscriptionType { name }
                types {
                  name
                  kind
                  description
                  fields {
                    name
                    type { name kind }
                  }
                }
              }
            }
            """;

        given()
            .contentType(ContentType.JSON)
            .body(buildGraphQLRequest(introspectionQuery, null))
        .when()
            .post(GRAPHQL_ENDPOINT)
        .then()
            .statusCode(200)
            .body("data.__schema.queryType.name", equalTo("Query"))
            .body("data.__schema.types", hasSize(greaterThan(0)));
    }

    @Test
    public void testBatchQueries() {
        String batchQuery = """
            query BatchQuery($userId1: ID!, $userId2: ID!) {
              user1: user(id: $userId1) {
                id
                name
              }
              user2: user(id: $userId2) {
                id
                name
                email
              }
            }
            """;

        Map<String, Object> variables = Map.of(
            "userId1", 123,
            "userId2", 456
        );

        given()
            .contentType(ContentType.JSON)
            .body(buildGraphQLRequest(batchQuery, variables))
        .when()
            .post(GRAPHQL_ENDPOINT)
        .then()
            .statusCode(200)
            .body("data.user1.id", equalTo(123))
            .body("data.user2.id", equalTo(456))
            .body("data.user1.name", notNullValue())
            .body("data.user2.name", notNullValue());
    }

    @Test
    public void testNullHandlingAndOptionalFields() {
        String queryWithOptionalFields = """
            query {
              user(id: 999) {  # Non-existent user
                id
                name
                optionalField
              }
            }
            """;

        given()
            .contentType(ContentType.JSON)
            .body(buildGraphQLRequest(queryWithOptionalFields, null))
        .when()
            .post(GRAPHQL_ENDPOINT)
        .then()
            .statusCode(200)
            .body("data.user", nullValue())  // User might be null
            .body("errors", nullValue());     // No errors for null data
    }

    @Test
    public void testPerformanceWithResponseTime() {
        String simpleQuery = """
            query {
              users(first: 5) {
                edges {
                  node {
                    id
                    name
                  }
                }
              }
            }
            """;

        given()
            .contentType(ContentType.JSON)
            .body(buildGraphQLRequest(simpleQuery, null))
        .when()
            .post(GRAPHQL_ENDPOINT)
        .then()
            .statusCode(200)
            .time(lessThan(1000L))  // Response time should be < 1 second
            .body("data.users.edges", hasSize(lessThanOrEqualTo(5)));
    }
}

