public class AdvancedGraphQLTestingFramework {

    private static final ObjectMapper objectMapper = new ObjectMapper();
    private static final String TEST_DATA_DIR = "src/test/resources/graphql/";

    // GraphQL Client Utility
    public static class GraphQLClient {

        public static Response executeQuery(String query, Map<String, Object> variables) {
            return execute(query, variables, null);
