        public static Response execute(String operation, 
                                      Map<String, Object> variables,
                                      Map<String, String> headers) {

            Map<String, Object> requestBody = Map.of(
                "query", operation,
                "variables", variables != null ? variables : Map.of()
            );

            var request = given()
                .contentType(ContentType.JSON)
                .body(requestBody);

            if (headers != null) {
                headers.forEach(request::header);
            }

            return request.post("/graphql");
        }

        public static Map<String, Object> extractData(Response response) {
            return response.jsonPath().getMap("data");
        }

        public static List<Map<String, Object>> extractErrors(Response response) {
            return response.jsonPath().getList("errors");
        }
    }

    // Schema Validator
    public static class SchemaValidator {

        public static void validateFieldExists(String typeName, String fieldName) {
            String introspectionQuery = String.format("""
                {
                  __type(name: \"%s\") {
                    fields {
                      name
                    }
                  }
                }
                """, typeName);

            Response response = GraphQLClient.executeQuery(introspectionQuery, null);
            List<String> fieldNames = response.jsonPath()
                .getList("data.__type.fields.name");

            assertThat("Field " + fieldName + " should exist in type " + typeName,
                fieldNames, hasItem(fieldName));
        }

        public static void validateTypeKind(String typeName, String expectedKind) {
            String query = String.format("""
                {
                  __type(name: \"%s\") {
                    kind
                  }
                }
                """, typeName);

            Response response = GraphQLClient.executeQuery(query, null);
            String actualKind = response.jsonPath().getString("data.__type.kind");

            assertThat(actualKind, equalTo(expectedKind));
        }
    }

    // Query Loader from Files
    public static class QueryLoader {

        public static String loadQuery(String fileName) throws IOException {
            return Files.readString(Paths.get(TEST_DATA_DIR + fileName + ".graphql"));
        }

        public static Map<String, Object> loadVariables(String fileName) throws IOException {
            return objectMapper.readValue(
                new File(TEST_DATA_DIR + fileName + ".json"),
                Map.class
            );
        }
    }

    // Test Examples
    @Test
    public void testSchemaConsistency() {
        SchemaValidator.validateFieldExists("User", "email");
        SchemaValidator.validateFieldExists("User", "posts");
        SchemaValidator.validateTypeKind("User", "OBJECT");
        SchemaValidator.validateTypeKind("UserRole", "ENUM");
    }

    @Test
    public void testFromFile() throws IOException {
        String query = QueryLoader.loadQuery("get-user-with-posts");
        Map<String, Object> variables = QueryLoader.loadVariables("user-variables");

        Response response = GraphQLClient.executeQuery(query, variables);

        assertThat(response.statusCode(), is(200));
        assertThat(GraphQLClient.extractErrors(response), empty());

        Map<String, Object> data = GraphQLClient.extractData(response);
        assertThat(data, hasKey("user"));
    }

    @ParameterizedTest
    @MethodSource("provideInvalidQueries")
    public void testInvalidQueries(String invalidQuery) {
        Response response = GraphQLClient.executeQuery(invalidQuery, null);

        assertThat(response.statusCode(), is(200));
        List<Map<String, Object>> errors = GraphQLClient.extractErrors(response);
        assertThat(errors, not(empty()));

        // All errors should have a message
        errors.forEach(error -> {
            assertThat(error, hasKey("message"));
            assertThat(error.get("message"), not(emptyOrNullString()));
        });
    }

    private static Stream<String> provideInvalidQueries() {
        return Stream.of(
            "query { invalidField }",
            "query { user(id: \"invalid\") { invalidField } }",
            "",  // Empty query
            "not a valid graphql query",
            "query { user(id: 123) { id name } user(id: 456) { id name } }"  // Duplicate field
        );
    }

    @Test
    public void testPerformanceBenchmark() {
        String query = """
            query {
              users(first: 100) {
                edges {
                  node {
                    id
                    name
                    email
                    posts(first: 10) {
                      edges {
                        node {
                          id
                          title
                        }
                      }
                    }
                  }
                }
              }
            }
            """;

        long startTime = System.currentTimeMillis();

        Response response = GraphQLClient.executeQuery(query, null);

        long endTime = System.currentTimeMillis();
        long duration = endTime - startTime;

        assertThat(response.statusCode(), is(200));

        // Performance assertions
        assertThat("Query should complete within 5 seconds", duration, lessThan(5000L));

        // Also check response size isn't too large
        String responseBody = response.getBody().asString();
        assertThat("Response size should be reasonable", 
            responseBody.length(), lessThan(100000));  // Less than 100KB
    }

    @Test
    public void testDataConsistency() {
        // Test that same query returns consistent results
        String query = """
            query {
              user(id: 1) {
                id
                name
                email
              }
            }
            """;

        Response response1 = GraphQLClient.executeQuery(query, null);
        Response response2 = GraphQLClient.executeQuery(query, null);

        Map<String, Object> data1 = GraphQLClient.extractData(response1);
        Map<String, Object> data2 = GraphQLClient.extractData(response2);

        // Data should be the same (assuming no updates between requests)
        assertThat(data1, equalTo(data2));
    }
}

