import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';

// Custom metric for error rate
const errorRate = new Rate('errors');

// Test configuration
export let options = {
  stages: [
    { duration: '30s', target: 10 },  // Ramp up
    { duration: '1m', target: 50 },   // Stay at load
    { duration: '30s', target: 0 },   // Ramp down
  ],
  thresholds: {
    'http_req_duration': ['p(95)<500'],  // 95% under 500ms
    'errors': ['rate<0.01'],             // Error rate < 1%
  },
};

// GraphQL query
export default function() {
  const query = `
    query GetProducts($category: String!) {
      products(category: $category, first: 10) {
        edges {
          node {
            id
            name
            price
            category
          }
        }
      }
    }
  `;

  const variables = {
    category: 'electronics'
  };

  const payload = JSON.stringify({
    query: query,
    variables: variables
  });

  const headers = {
    'Content-Type': 'application/json',
    'Authorization': 'Bearer test-token'
  };

  const response = http.post('http://localhost:8080/graphql', payload, { headers: headers });

  // Validate response
  const success = check(response, {
    'status is 200': (r) => r.status === 200,
    'response has data': (r) => r.json('data') !== null,
    'no errors in response': (r) => r.json('errors') === null,
    'has products': (r) => r.json('data.products.edges.length') > 0
  });

  // Record error if any check failed
  errorRate.add(!success);

  sleep(1);
}

// api-load-test.js
import http from 'k6/http';
import { check, sleep, group, fail } from 'k6';
import { Rate, Trend, Counter } from 'k6/metrics';
import { htmlReport } from 'https://raw.githubusercontent.com/benc-uk/k6-reporter/main/dist/bundle.js';
import { textSummary } from 'https://jslib.k6.io/k6-summary/0.0.1/index.js';
import encoding from 'k6/encoding';

// Custom metrics
const errorRate = new Rate('errors');
const responseTimeTrend = new Trend('response_time_trend');
const successfulLogins = new Counter('successful_logins');
const failedCheckouts = new Counter('failed_checkouts');

// Test configuration
export const options = {
  scenarios: {
    // Scenario 1: Normal browsing traffic
    browsing: {
      executor: 'ramping-vus',
      startVUs: 10,
      stages: [
        { duration: '2m', target: 50 },    // Ramp up
        { duration: '5m', target: 50 },    // Stay at load
        { duration: '2m', target: 100 },   // Increase load
        { duration: '5m', target: 100 },   // Stay at peak
        { duration: '2m', target: 0 },     // Ramp down
      ],
      gracefulRampDown: '30s',
      tags: { scenario: 'browsing' },
    },

    // Scenario 2: Checkout spike
    checkout: {
      executor: 'constant-vus',
      vus: 20,
      duration: '10m',
      startTime: '3m',  // Start after browsing has warmed up
      tags: { scenario: 'checkout' },
    },

    // Scenario 3: Admin operations (lower volume)
    admin: {
      executor: 'per-vu-iterations',
      vus: 5,
      iterations: 10,
      maxDuration: '15m',
      tags: { scenario: 'admin' },
    },
  },

  thresholds: {
    // Global thresholds
    'http_req_duration': ['p(95)<500', 'p(99)<1000'],
    'http_req_failed': ['rate<0.01'],  // Less than 1% errors
    'errors': ['rate<0.05'],

    // Scenario-specific thresholds
    'http_req_duration{scenario:browsing}': ['p(95)<300'],
    'http_req_duration{scenario:checkout}': ['p(95)<1000'],
    'http_req_duration{scenario:admin}': ['p(95)<2000'],

    // Custom metric thresholds
    'response_time_trend': ['avg<250', 'med<200'],
    'successful_logins': ['count>100'],
  },

  // Performance optimization
  discardResponseBodies: true,  // Don't store response bodies
  noConnectionReuse: false,     // Reuse connections
  userAgent: 'k6-load-test/1.0',

  // Extensions
  ext: {
    loadimpact: {
      name: 'E-Commerce API Load Test',
      projectID: 123456,
      distribution: {
        'amazon:us:ashburn': { loadZone: 'amazon:us:ashburn', percent: 100 },
      },
    },
  },
};

// Test data (could also load from CSV/JSON)
const testUsers = [
  { username: 'user1@test.com', password: 'password123' },
  { username: 'user2@test.com', password: 'password456' },
  // ... more test users
];

const products = [
  { id: 101, category: 'electronics' },
  { id: 102, category: 'clothing' },
  { id: 103, category: 'books' },
];

// Setup function - runs once at beginning
export function setup() {
  console.log('Test setup: Fetching configuration');

  // Could fetch configuration from external source
  const config = {
    baseUrl: __ENV.BASE_URL || 'https://api.example.com',
    apiVersion: 'v1',
    adminToken: __ENV.ADMIN_TOKEN || 'test-admin-token',
  };

  // Warm up cache if needed
  const warmupResponse = http.get(`${config.baseUrl}/health`);
  check(warmupResponse, {
    'warmup successful': (r) => r.status === 200,
  });

  return config;
}

// Main test execution
export default function (config) {
  // Randomly select test user and product
  const user = testUsers[Math.floor(Math.random() * testUsers.length)];
  const product = products[Math.floor(Math.random() * products.length)];

  // Group related requests for better reporting
  group('Authentication Flow', () => {
    const loginPayload = JSON.stringify({
      username: user.username,
      password: user.password,
    });

    const loginParams = {
      headers: {
        'Content-Type': 'application/json',
        'User-Agent': 'k6-load-test',
      },
      tags: { endpoint: 'login' },
    };

    const loginRes = http.post(
      `${config.baseUrl}/${config.apiVersion}/auth/login`,
      loginPayload,
      loginParams
    );

    // Validate login response
    const loginCheck = check(loginRes, {
      'login status is 200': (r) => r.status === 200,
      'login has auth token': (r) => r.json('token') !== null,
      'login response time acceptable': (r) => r.timings.duration < 1000,
    });

    if (!loginCheck) {
      errorRate.add(1);
      fail('Login failed');
      return; // Skip rest of iteration if login fails
    }

    successfulLogins.add(1);
    responseTimeTrend.add(loginRes.timings.duration);

    const authToken = loginRes.json('token');
    const userId = loginRes.json('user.id');

    // Store auth token for subsequent requests
    config.authToken = authToken;
    config.userId = userId;

    sleep(Math.random() * 2 + 1); // Think time 1-3 seconds
  });

  group('Browse Products', () => {
    const browseParams = {
      headers: {
        'Authorization': `Bearer ${config.authToken}`,
      },
      tags: { endpoint: 'browse' },
    };

    const browseRes = http.get(
      `${config.baseUrl}/${config.apiVersion}/products?category=${product.category}&page=1`,
      browseParams
    );

    check(browseRes, {
      'browse status is 200': (r) => r.status === 200,
      'browse returns products': (r) => r.json('products').length > 0,
    });

    responseTimeTrend.add(browseRes.timings.duration);

    sleep(Math.random() * 3 + 2); // Think time 2-5 seconds
  });

  // Only 30% of users proceed to checkout
  if (Math.random() < 0.3) {
    group('Checkout Process', () => {
      // Add to cart
      const cartPayload = JSON.stringify({
        productId: product.id,
        quantity: Math.floor(Math.random() * 3) + 1,
      });

      const cartParams = {
        headers: {
          'Authorization': `Bearer ${config.authToken}`,
          'Content-Type': 'application/json',
        },
        tags: { endpoint: 'add-to-cart' },
      };

      const cartRes = http.post(
        `${config.baseUrl}/${config.apiVersion}/cart/items`,
        cartPayload,
        cartParams
      );

      check(cartRes, {
        'add to cart successful': (r) => r.status === 201,
      });

      sleep(1);

      // Checkout
      const checkoutPayload = JSON.stringify({
        paymentMethod: 'credit_card',
        shippingAddress: {
          street: '123 Test St',
          city: 'Testville',
          zipCode: '12345',
        },
      });

      const checkoutRes = http.post(
        `${config.baseUrl}/${config.apiVersion}/checkout`,
        checkoutPayload,
        {
          headers: {
            'Authorization': `Bearer ${config.authToken}`,
            'Content-Type': 'application/json',
          },
          tags: { endpoint: 'checkout' },
        }
      );

      const checkoutCheck = check(checkoutRes, {
        'checkout status is 200': (r) => r.status === 200,
        'checkout returns order id': (r) => r.json('orderId') !== null,
      });

      if (!checkoutCheck) {
        failedCheckouts.add(1);
        errorRate.add(1);
      }

      responseTimeTrend.add(checkoutRes.timings.duration);
    });
  }

  // Admin operations (only for admin users)
  if (user.username.includes('admin')) {
    group('Admin Operations', () => {
      const adminParams = {
        headers: {
          'Authorization': `Bearer ${config.authToken}`,
          'X-Admin-Token': config.adminToken,
        },
        tags: { endpoint: 'admin' },
      };

      const statsRes = http.get(
        `${config.baseUrl}/${config.apiVersion}/admin/stats`,
        adminParams
      );

      check(statsRes, {
        'admin stats accessible': (r) => r.status === 200,
      });
    });
  }
}

// Teardown function - runs once at end
export function teardown(config) {
  console.log('Test teardown: Cleaning up test data');

  // Could clean up test data created during test
  const cleanupParams = {
    headers: {
      'Authorization': `Bearer ${config.adminToken}`,
    },
  };

  // Example: Clean up test orders
  http.del(
    `${config.baseUrl}/${config.apiVersion}/admin/test-orders`,
    null,
    cleanupParams
  );
}

// Generate reports
export function handleSummary(data) {
  console.log('Preparing summary reports...');

  return {
    'results/summary.html': htmlReport(data),
    'results/summary.json': JSON.stringify(data, null, 2),
    'stdout': textSummary(data, { indent: ' ', enableColors: true }),
  };
}

