// ProductServiceClient.java - The actual client that will use the pact
public class ProductServiceClient {

    private final RestTemplate restTemplate;
    private final String baseUrl;

    public ProductServiceClient(RestTemplate restTemplate, String baseUrl) {
        this.restTemplate = restTemplate;
        this.baseUrl = baseUrl;
    }

    public Product getProduct(String productId, String authToken) {
        String url = baseUrl + "/products/" + productId;

        HttpHeaders headers = new HttpHeaders();
        headers.set("Authorization", "Bearer " + authToken);
        HttpEntity<String> entity = new HttpEntity<>(headers);

        ResponseEntity<Product> response = restTemplate.exchange(
            url, HttpMethod.GET, entity, Product.class
        );

        if (response.getStatusCode().is2xxSuccessful()) {
            return response.getBody();
        } else if (response.getStatusCode() == HttpStatus.NOT_FOUND) {
            throw new ProductNotFoundException("Product not found: " + productId);
        } else {
            throw new ProductServiceException("Failed to get product: " + response.getStatusCode());
        }
    }

    public ProductList getProducts(String category, int page, int size) {
        String url = String.format("%s/products?category=%s&page=%d&size=%d", 
            baseUrl, category, page, size);

        ResponseEntity<ProductList> response = restTemplate.getForEntity(url, ProductList.class);

        if (response.getStatusCode().is2xxSuccessful()) {
            return response.getBody();
        } else {
            throw new ProductServiceException("Failed to get products: " + response.getStatusCode());
        }
    }
}

