        for (int i = 1; i <= 50; i++) {
            Product product = new Product();
            product.setId(UUID.randomUUID());
            product.setName("Electronics Product " + i);
            product.setDescription("Description for electronics product " + i);
            product.setPrice(new BigDecimal("99.99"));
