def response = context.response
if (response) {
    def responseXml = new XmlSlurper().parseText(response.getContentAsString())

    // Extract values
    def price = responseXml.Body.GetProductResponse.Product.price.text()
    def inStock = responseXml.Body.GetProductResponse.Product.inStock.text()

    // Business rule: Price must be positive
    assert price.toDouble() > 0 : "Price must be positive: " + price

    // Business rule: If inStock is false, stockQuantity should be 0
    if (inStock == "false") {
