package com.company.api.framework.infrastructure;

import io.restassured.RestAssured;
import io.restassured.response.Response;
import io.restassured.specification.RequestSpecification;
import java.util.Map;

public class HttpClient {

    private RequestSpecification requestSpec;

    public HttpClient(String baseUrl) {
        this.requestSpec = RestAssured.given()
            .baseUri(baseUrl)
            .contentType("application/json")
            .log().all();
    }

    public Response get(String path, Map<String, String> headers) {
        RequestSpecification spec = requestSpec;
        if (headers != null) {
            spec = spec.headers(headers);
        }
        return spec.get(path);
    }

    public Response post(String path, Object body, Map<String, String> headers) {
        RequestSpecification spec = requestSpec;
        if (headers != null) {
            spec = spec.headers(headers);
        }
        return spec.body(body).post(path);
    }

    public Response put(String path, Object body, Map<String, String> headers) {
        RequestSpecification spec = requestSpec;
        if (headers != null) {
            spec = spec.headers(headers);
        }
        return spec.body(body).put(path);
    }

    public Response delete(String path, Map<String, String> headers) {
        RequestSpecification spec = requestSpec;
        if (headers != null) {
            spec = spec.headers(headers);
        }
        return spec.delete(path);
    }
}

