package com.company.api.framework.services;

import com.company.api.framework.clients.UserServiceClient;
import com.company.api.framework.models.User;
import io.restassured.response.Response;

public class UserRegistrationService {

    private final UserServiceClient userClient;

    public UserRegistrationService(String baseUrl) {
        this.userClient = new UserServiceClient(baseUrl);
    }

    public User registerNewUser(String email, String password, String firstName, String lastName) {
        User newUser = User.builder()
            .email(email)
            .password(password)
            .firstName(firstName)
            .lastName(lastName)
            .build();

        Response response = userClient.createUser(newUser);

        if (response.getStatusCode() == 201) {
            return response.as(User.class);
        } else {
            throw new RuntimeException("Failed to register user: " + response.getStatusCode());
        }
    }

    public User registerAndVerifyUser(String email, String password, String firstName, String lastName) {
        // Multi-step operation
        User user = registerNewUser(email, password, firstName, lastName);

        // Verify user exists
        Response getResponse = userClient.getUser(user.getId());
        if (getResponse.getStatusCode() != 200) {
            throw new RuntimeException("User registration verification failed");
        }

        return user;
    }

    public void deleteUserIfExists(String userId) {
        try {
            Response getResponse = userClient.getUser(userId);
            if (getResponse.getStatusCode() == 200) {
                userClient.deleteUser(userId);
            }
        } catch (Exception e) {
            // User doesn't exist, which is fine
        }
    }
}

