        this.apiClient = apiClient;
        this.validator = validator;
    }

    @Override
    public User createUser(UserRequest request) {
        // Validate request
        validator.validateCreateRequest(request);

        // Build API request
        ApiRequest apiRequest = UserRequestBuilder.buildCreateRequest(request);

        // Execute API call
        ApiResponse response = apiClient.createUser(apiRequest);

        // Validate response
        validator.validateCreateResponse(response);

        // Transform to domain model
        return UserMapper.fromApiResponse(response);
    }

    @Override
    public User registerUserWithDefaultProfile(String email, String password) {
        // Complex business operation
        UserRequest request = UserRequest.builder()
            .email(email)
            .password(password)
            .firstName("New")
            .lastName("User")
            .profileType("DEFAULT")
            .sendWelcomeEmail(true)
            .build();

        User user = createUser(request);

        // Additional setup for default profile
        setupDefaultPreferences(user.getId());
        assignDefaultRole(user.getId());

        return user;
    }

    @Override
    public User activateUser(String userId) {
        // Get current user
        User user = getUser(userId);

        // Check if already active
        if (user.isActive()) {
            return user;
        }

        // Build activation request
        UserUpdateRequest updateRequest = UserUpdateRequest.builder()
            .active(true)
            .activationDate(LocalDateTime.now())
            .build();

        // Update user
        return updateUser(userId, updateRequest);
    }

