public class TestDataFactory {

    // User Factory Methods
    public static User createBasicUser() {
        return User.builder()
            .id(UUID.randomUUID().toString())
            .email("user" + System.currentTimeMillis() + "@example.com")
            .firstName("Test")
            .lastName("User")
            .active(true)
            .createdAt(LocalDateTime.now())
            .build();
    }

    public static User createAdminUser() {
        User user = createBasicUser();
        user.setRoles(List.of("ADMIN", "USER"));
        user.setPermissions(List.of("READ", "WRITE", "DELETE", "MANAGE_USERS"));
        return user;
    }

    public static User createInactiveUser() {
        User user = createBasicUser();
        user.setActive(false);
        user.setDeactivatedAt(LocalDateTime.now());
        return user;
    }

    public static User createUserWithSubscription(String subscriptionType) {
        User user = createBasicUser();
        user.setSubscription(Subscription.builder()
            .type(subscriptionType)
            .startDate(LocalDateTime.now())
            .endDate(LocalDateTime.now().plusMonths(1))
            .autoRenew(true)
            .build());
        return user;
    }

    // Order Factory Methods
    public static Order createSimpleOrder() {
        return Order.builder()
            .id(UUID.randomUUID().toString())
            .userId(UUID.randomUUID().toString())
            .status("PENDING")
            .totalAmount(99.99)
            .items(List.of(createOrderItem()))
            .build();
    }

    public static Order createLargeOrder() {
        return Order.builder()
            .id(UUID.randomUUID().toString())
            .userId(UUID.randomUUID().toString())
            .status("PENDING")
            .totalAmount(999.99)
            .items(List.of(
                createOrderItem("Premium Product", 299.99, 3),
                createOrderItem("Standard Product", 99.99, 2)
            ))
            .shippingAddress(createShippingAddress())
            .billingAddress(createBillingAddress())
            .build();
    }

    public static Order createOrderWithDiscount(String discountCode, double discountAmount) {
        Order order = createSimpleOrder();
        order.setDiscount(Discount.builder()
            .code(discountCode)
            .amount(discountAmount)
            .type("PERCENTAGE")
            .build());
        order.setTotalAmount(order.getTotalAmount() - discountAmount);
        return order;
    }

    // Builder Pattern for Complex Requests
    public static class UserRequestBuilder {
        private String email;
        private String password;
        private String firstName;
        private String lastName;
        private String phone;
        private String address;
        private boolean sendWelcomeEmail = true;
        private boolean acceptTerms = true;
        private List<String> roles = new ArrayList<>();

        public UserRequestBuilder withEmail(String email) {
            this.email = email;
            return this;
        }

        public UserRequestBuilder withPassword(String password) {
            this.password = password;
            return this;
        }

        public UserRequestBuilder withName(String firstName, String lastName) {
            this.firstName = firstName;
            this.lastName = lastName;
            return this;
        }

        public UserRequestBuilder withContactInfo(String phone, String address) {
            this.phone = phone;
            this.address = address;
            return this;
        }

        public UserRequestBuilder withWelcomeEmail(boolean sendWelcomeEmail) {
            this.sendWelcomeEmail = sendWelcomeEmail;
            return this;
        }

        public UserRequestBuilder withRole(String role) {
            this.roles.add(role);
            return this;
        }

        public UserRequest build() {
            UserRequest request = new UserRequest();
            request.setEmail(this.email);
            request.setPassword(this.password);
            request.setFirstName(this.firstName);
            request.setLastName(this.lastName);
            request.setPhone(this.phone);
            request.setAddress(this.address);
            request.setSendWelcomeEmail(this.sendWelcomeEmail);
            request.setAcceptTerms(this.acceptTerms);
            request.setRoles(this.roles);
            return request;
        }
    }

    // Abstract Factory for Environment-Specific Data
    public interface TestDataFactoryAbstract {
        User createUser();
        Order createOrder();
        Product createProduct();
    }

