class TestDataLoader {

    public List<User> loadUsersFromCsv(String filePath) {
        List<User> users = new ArrayList<>();

        try (BufferedReader br = new BufferedReader(new FileReader(filePath))) {
            String line;
            boolean headerSkipped = false;

            while ((line = br.readLine()) != null) {
                if (!headerSkipped) {
                    headerSkipped = true;
                    continue;
                }

                String[] values = line.split(",");
                if (values.length >= 4) {
                    User user = User.builder()
                        .email(values[0])
                        .firstName(values[1])
                        .lastName(values[2])
                        .phone(values[3])
                        .build();
                    users.add(user);
                }
            }
        } catch (IOException e) {
            throw new RuntimeException("Failed to load users from CSV", e);
        }

        return users;
    }

    public List<User> loadUsersFromJson(String filePath) {
        try {
