// CONFIGURATION LOADER
package com.company.api.config;

import org.springframework.core.env.Environment;
import org.springframework.stereotype.Component;
import java.util.Map;
import java.util.HashMap;

@Component
public class ConfigurationLoader {

    private final Environment env;
    private final Map<String, String> configCache;

    public ConfigurationLoader(Environment env) {
        this.env = env;
        this.configCache = new HashMap<>();
    }

    public String getProperty(String key) {
        return getProperty(key, null);
    }

    public String getProperty(String key, String defaultValue) {
        // Check cache first
        if (configCache.containsKey(key)) {
            return configCache.get(key);
        }

        // Get from environment (with precedence)
        String value = null;

        // 1. Check system property
        value = System.getProperty(key);

        // 2. Check environment variable
        if (value == null) {
            String envKey = key.toUpperCase().replace('.', '_');
            value = System.getenv(envKey);
        }

        // 3. Check Spring environment (from config files)
        if (value == null) {
            value = env.getProperty(key);
        }

        // 4. Use default if still null
        if (value == null) {
            value = defaultValue;
        }

        // Cache the value
        if (value != null) {
            configCache.put(key, value);
        }

        return value;
    }

    public int getIntProperty(String key, int defaultValue) {
        String value = getProperty(key);
        if (value == null) {
            return defaultValue;
        }
        try {
            return Integer.parseInt(value);
        } catch (NumberFormatException e) {
            return defaultValue;
        }
    }

    public boolean getBooleanProperty(String key, boolean defaultValue) {
        String value = getProperty(key);
        if (value == null) {
            return defaultValue;
        }
        return Boolean.parseBoolean(value);
    }

    public String[] getArrayProperty(String key, String[] defaultValue) {
        String value = getProperty(key);
        if (value == null) {
            return defaultValue;
        }
        return value.split(",");
    }

    public void clearCache() {
        configCache.clear();
    }

    public Map<String, String> getAllProperties() {
        Map<String, String> allProps = new HashMap<>();

        // System properties
        System.getProperties().forEach((k, v) -> 
            allProps.put(k.toString(), v.toString())
        );

        // Environment variables
        System.getenv().forEach(allProps::put);

        return allProps;
    }
}

