package com.company.api.tests;

import com.company.api.config.ConfigurationLoader;
import com.company.api.config.AppConfig;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest
public class ConfigurationTests {

    @Autowired
    private AppConfig appConfig;

    @Autowired
    private ConfigurationLoader configLoader;

    @Test
    public void testAppConfig() {
        assertNotNull(appConfig);
        assertNotNull(appConfig.getName());
        assertNotNull(appConfig.getVersion());

        System.out.println("App: " + appConfig.getName() + " v" + appConfig.getVersion());
    }

    @Test
    public void testLoggingConfig() {
        assertNotNull(appConfig.getLogging());
        assertNotNull(appConfig.getLogging().getLevel());
        assertNotNull(appConfig.getLogging().getFile());

        System.out.println("Logging level: " + appConfig.getLogging().getLevel());
        System.out.println("Log file: " + appConfig.getLogging().getFile());
    }

    @Test
    public void testApiConfig() {
        assertNotNull(appConfig.getApis());

        // Assuming we have an API named 'main'
        ApiConfig mainApi = appConfig.getApis().get("main");
        if (mainApi != null) {
            assertNotNull(mainApi.getBaseUrl());
            assertTrue(mainApi.getTimeout() > 0);

            System.out.println("API Base URL: " + mainApi.getBaseUrl());
            System.out.println("API Timeout: " + mainApi.getTimeout() + "ms");
        }
    }

    @Test
    public void testConfigurationLoader() {
        // Test getting properties
        String appName = configLoader.getProperty("app.name");
        assertNotNull(appName);

        // Test with default value
        String nonExistent = configLoader.getProperty("non.existent.key", "default");
        assertEquals("default", nonExistent);

        // Test integer property
        int timeout = configLoader.getIntProperty("app.test.defaultTimeout", 30000);
        assertTrue(timeout > 0);

        // Test boolean property
        boolean reportingEnabled = configLoader.getBooleanProperty("app.reporting.enabled", false);

        System.out.println("App Name from loader: " + appName);
        System.out.println("Timeout: " + timeout + "ms");
        System.out.println("Reporting enabled: " + reportingEnabled);
    }

    @Test
    public void testEnvironmentSpecificConfig() {
        // This test will use different config based on active profile
        String activeProfile = System.getProperty("spring.profiles.active");

        if (activeProfile == null) {
            activeProfile = "default";
        }

        System.out.println("Active profile: " + activeProfile);

        // Different assertions based on profile
        if ("dev".equals(activeProfile)) {
            assertTrue(appConfig.getApis().get("main").getBaseUrl().contains("localhost"));
        } else if ("ci".equals(activeProfile)) {
            assertTrue(appConfig.getApis().get("main").getBaseUrl().contains("ci.company.com"));
