// TEST REPORT GENERATOR
package com.company.api.reporting;

import com.company.api.models.TestResult;
import com.company.api.models.TestSuiteResult;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import org.thymeleaf.TemplateEngine;
import org.thymeleaf.context.Context;
import org.thymeleaf.templatemode.TemplateMode;
import org.thymeleaf.templateresolver.ClassLoaderTemplateResolver;
import java.io.*;
import java.nio.file.*;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.*;

public class TestReportGenerator {

    private final String outputDir;
    private final ObjectMapper objectMapper;
    private final TemplateEngine templateEngine;

    public TestReportGenerator(String outputDir) {
        this.outputDir = outputDir;
        this.objectMapper = new ObjectMapper();
        this.objectMapper.enable(SerializationFeature.INDENT_OUTPUT);

        // Initialize template engine for HTML reports
        this.templateEngine = new TemplateEngine();
        ClassLoaderTemplateResolver templateResolver = new ClassLoaderTemplateResolver();
        templateResolver.setPrefix("templates/");
        templateResolver.setSuffix(".html");
        templateResolver.setTemplateMode(TemplateMode.HTML);
        templateResolver.setCharacterEncoding("UTF-8");
        templateEngine.setTemplateResolver(templateResolver);

        // Create output directory if it doesn't exist
        try {
            Files.createDirectories(Paths.get(outputDir));
        } catch (IOException e) {
            throw new RuntimeException("Failed to create report directory", e);
        }
    }

    public void generateReports(TestSuiteResult suiteResult) {
        // Generate timestamp for report files
        String timestamp = LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyyMMdd_HHmmss"));
        String reportBaseName = "test_report_" + timestamp;

        // Generate JSON report
        generateJsonReport(suiteResult, reportBaseName);

        // Generate HTML report
        generateHtmlReport(suiteResult, reportBaseName);

        // Generate JUnit XML report
        generateJunitReport(suiteResult, reportBaseName);

        // Generate summary report
        generateSummaryReport(suiteResult, reportBaseName);
    }

    private void generateJsonReport(TestSuiteResult suiteResult, String baseName) {
        try {
            String jsonContent = objectMapper.writeValueAsString(suiteResult);
            String filePath = outputDir + "/" + baseName + ".json";
            Files.write(Paths.get(filePath), jsonContent.getBytes());
            System.out.println("JSON report generated: " + filePath);
        } catch (IOException e) {
            System.err.println("Failed to generate JSON report: " + e.getMessage());
        }
    }

    private void generateHtmlReport(TestSuiteResult suiteResult, String baseName) {
        try {
            // Prepare context for template
            Context context = new Context();
            context.setVariable("suite", suiteResult);
            context.setVariable("timestamp", LocalDateTime.now().format(
                DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")));
            context.setVariable("passedCount", suiteResult.getPassedCount());
            context.setVariable("failedCount", suiteResult.getFailedCount());
            context.setVariable("skippedCount", suiteResult.getSkippedCount());
            context.setVariable("totalCount", suiteResult.getTotalCount());
            context.setVariable("passPercentage", suiteResult.getPassPercentage());

            // Calculate execution time
            long durationSeconds = suiteResult.getDurationMillis() / 1000;
            context.setVariable("duration", durationSeconds + " seconds");

            // Process template
            String htmlContent = templateEngine.process("test_report", context);

            // Write to file
            String filePath = outputDir + "/" + baseName + ".html";
            Files.write(Paths.get(filePath), htmlContent.getBytes());
            System.out.println("HTML report generated: " + filePath);

        } catch (Exception e) {
            System.err.println("Failed to generate HTML report: " + e.getMessage());
        }
    }

    private void generateJunitReport(TestSuiteResult suiteResult, String baseName) {
        try {
            StringBuilder xml = new StringBuilder();
            xml.append("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n");
            xml.append("<testsuite name=\"")
               .append(suiteResult.getName())
               .append("\" tests=\"")
               .append(suiteResult.getTotalCount())
               .append("\" failures=\"")
               .append(suiteResult.getFailedCount())
               .append("\" skipped=\"")
               .append(suiteResult.getSkippedCount())
               .append("\" time=\"")
               .append(suiteResult.getDurationMillis() / 1000.0)
               .append("\">\n");

            for (TestResult testResult : suiteResult.getTestResults()) {
                xml.append("  <testcase name=\"")
                   .append(testResult.getName())
                   .append("\" classname=\"")
                   .append(testResult.getClassName())
                   .append("\" time=\"")
                   .append(testResult.getDurationMillis() / 1000.0)
                   .append("\">\n");

                if (!testResult.isPassed()) {
                    xml.append("    <failure message=\"")
                       .append(escapeXml(testResult.getErrorMessage()))
                       .append("\">")
                       .append(escapeXml(testResult.getStackTrace()))
                       .append("</failure>\n");
                }

                xml.append("  </testcase>\n");
            }

            xml.append("</testsuite>");

            String filePath = outputDir + "/" + baseName + ".xml";
            Files.write(Paths.get(filePath), xml.toString().getBytes());
            System.out.println("JUnit XML report generated: " + filePath);

        } catch (IOException e) {
            System.err.println("Failed to generate JUnit report: " + e.getMessage());
        }
    }

    private void generateSummaryReport(TestSuiteResult suiteResult, String baseName) {
        try {
            String summary = createSummaryText(suiteResult);
            String filePath = outputDir + "/" + baseName + "_summary.txt";
            Files.write(Paths.get(filePath), summary.getBytes());
            System.out.println("Summary report generated: " + filePath);
        } catch (IOException e) {
            System.err.println("Failed to generate summary report: " + e.getMessage());
        }
    }

    private String createSummaryText(TestSuiteResult suiteResult) {
        StringBuilder summary = new StringBuilder();
        summary.append("TEST EXECUTION SUMMARY\n");
        summary.append("====================\n\n");
        summary.append("Suite Name: ").append(suiteResult.getName()).append("\n");
        summary.append("Execution Time: ").append(LocalDateTime.now().format(
            DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"))).append("\n");
        summary.append("Duration: ").append(suiteResult.getDurationMillis() / 1000).append(" seconds\n\n");

        summary.append("Results:\n");
        summary.append("--------\n");
        summary.append("Total Tests: ").append(suiteResult.getTotalCount()).append("\n");
        summary.append("Passed: ").append(suiteResult.getPassedCount()).append("\n");
        summary.append("Failed: ").append(suiteResult.getFailedCount()).append("\n");
        summary.append("Skipped: ").append(suiteResult.getSkippedCount()).append("\n");
        summary.append("Pass Rate: ").append(String.format("%.2f", suiteResult.getPassPercentage())).append("%\n\n");

        if (suiteResult.getFailedCount() > 0) {
            summary.append("FAILED TESTS:\n");
            summary.append("------------\n");
            for (TestResult testResult : suiteResult.getTestResults()) {
                if (!testResult.isPassed()) {
                    summary.append("• ").append(testResult.getName()).append("\n");
                    summary.append("  Error: ").append(testResult.getErrorMessage()).append("\n\n");
                }
            }
        }

        summary.append("Detailed reports are available in:\n");
        summary.append("- ").append(baseName).append(".html (Interactive HTML)\n");
        summary.append("- ").append(baseName).append(".json (Machine-readable JSON)\n");
        summary.append("- ").append(baseName).append(".xml (JUnit XML)\n");

        return summary.toString();
    }

    private String escapeXml(String input) {
        if (input == null) return "";
        return input.replace("&", "&amp;")
                    .replace("<", "&lt;")
                    .replace(">", "&gt;")
                    .replace("\"", "&quot;")
                    .replace("'", "&apos;");
    }
}

// STRUCTURED LOGGER
package com.company.api.logging;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.HashMap;
import java.util.Map;

public class StructuredLogger {

    private final Logger logger;
    private final ObjectMapper objectMapper;
    private final String componentName;

    public StructuredLogger(Class<?> clazz) {
        this.logger = LoggerFactory.getLogger(clazz);
        this.objectMapper = new ObjectMapper();
        this.componentName = clazz.getSimpleName();
    }

    public StructuredLogger(String name) {
        this.logger = LoggerFactory.getLogger(name);
        this.objectMapper = new ObjectMapper();
        this.componentName = name;
    }

    public void info(String message) {
        info(message, null);
    }

    public void info(String message, Map<String, Object> context) {
        log("INFO", message, context, null);
    }

    public void debug(String message) {
        debug(message, null);
    }

    public void debug(String message, Map<String, Object> context) {
        log("DEBUG", message, context, null);
    }

    public void warn(String message) {
        warn(message, null);
    }

    public void warn(String message, Map<String, Object> context) {
        log("WARN", message, context, null);
    }

    public void error(String message) {
        error(message, null, null);
    }

    public void error(String message, Throwable throwable) {
        error(message, null, throwable);
    }

    public void error(String message, Map<String, Object> context, Throwable throwable) {
        log("ERROR", message, context, throwable);
    }

    public void logTestStart(String testName, Map<String, Object> testContext) {
        Map<String, Object> context = new HashMap<>();
        context.put("event", "test_start");
        context.put("test_name", testName);
        if (testContext != null) {
            context.putAll(testContext);
        }
        info("Test execution started", context);
    }

    public void logTestEnd(String testName, boolean passed, long durationMs, 
                           Map<String, Object> testContext) {
        Map<String, Object> context = new HashMap<>();
        context.put("event", "test_end");
        context.put("test_name", testName);
        context.put("status", passed ? "PASSED" : "FAILED");
        context.put("duration_ms", durationMs);
        if (testContext != null) {
            context.putAll(testContext);
        }
        info("Test execution completed", context);
    }

    public void logApiCall(String method, String url, int statusCode, long durationMs) {
        Map<String, Object> context = new HashMap<>();
        context.put("event", "api_call");
        context.put("method", method);
        context.put("url", url);
        context.put("status_code", statusCode);
        context.put("duration_ms", durationMs);
        info("API call executed", context);
    }

    private void log(String level, String message, Map<String, Object> context, Throwable throwable) {
        try {
            Map<String, Object> logEntry = new HashMap<>();
            logEntry.put("timestamp", LocalDateTime.now().format(DateTimeFormatter.ISO_DATE_TIME));
            logEntry.put("level", level);
            logEntry.put("component", componentName);
            logEntry.put("message", message);

            if (context != null) {
                logEntry.put("context", context);
            }

            if (throwable != null) {
                Map<String, Object> errorInfo = new HashMap<>();
                errorInfo.put("message", throwable.getMessage());
                errorInfo.put("type", throwable.getClass().getName());
                errorInfo.put("stack_trace", getStackTrace(throwable));
                logEntry.put("error", errorInfo);
            }

            String jsonLog = objectMapper.writeValueAsString(logEntry);

            // Log using appropriate SLF4J method
            switch (level) {
                case "DEBUG":
                    logger.debug(jsonLog);
                    break;
                case "INFO":
                    logger.info(jsonLog);
                    break;
                case "WARN":
                    logger.warn(jsonLog);
                    break;
                case "ERROR":
                    logger.error(jsonLog);
                    break;
                default:
                    logger.info(jsonLog);
            }

        } catch (JsonProcessingException e) {
            // Fallback to regular logging if JSON serialization fails
            logger.error("Failed to create structured log: " + e.getMessage());
            logger.error("Original message: " + message, throwable);
        }
    }

    private String getStackTrace(Throwable throwable) {
        if (throwable == null) return null;

        StringWriter sw = new StringWriter();
        PrintWriter pw = new PrintWriter(sw);
        throwable.printStackTrace(pw);
        return sw.toString();
    }
}

// PERFORMANCE METRICS COLLECTOR
package com.company.api.reporting;

import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.atomic.AtomicInteger;

public class PerformanceMetricsCollector {

    private final Map<String, ApiEndpointMetrics> endpointMetrics;
    private final AtomicInteger totalRequests;
    private final AtomicInteger failedRequests;
    private final AtomicLong totalResponseTime;

    public PerformanceMetricsCollector() {
        this.endpointMetrics = new ConcurrentHashMap<>();
        this.totalRequests = new AtomicInteger(0);
        this.failedRequests = new AtomicInteger(0);
        this.totalResponseTime = new AtomicLong(0);
    }

    public void recordApiCall(String endpoint, String method, int statusCode, long responseTimeMs) {
        totalRequests.incrementAndGet();
        totalResponseTime.addAndGet(responseTimeMs);

        if (statusCode >= 400) {
            failedRequests.incrementAndGet();
        }

        String key = method + " " + endpoint;
        endpointMetrics.computeIfAbsent(key, k -> new ApiEndpointMetrics(k))
                      .recordCall(statusCode, responseTimeMs);
    }

    public PerformanceReport generateReport() {
        PerformanceReport report = new PerformanceReport();
        report.setTotalRequests(totalRequests.get());
        report.setFailedRequests(failedRequests.get());
        report.setSuccessRate(calculateSuccessRate());
        report.setAverageResponseTime(calculateAverageResponseTime());

        List<EndpointPerformance> endpointPerformances = new ArrayList<>();
        for (ApiEndpointMetrics metrics : endpointMetrics.values()) {
            endpointPerformances.add(metrics.generateEndpointPerformance());
        }
        report.setEndpointPerformances(endpointPerformances);

        return report;
    }

    private double calculateSuccessRate() {
        if (totalRequests.get() == 0) return 100.0;
        return ((totalRequests.get() - failedRequests.get()) * 100.0) / totalRequests.get();
    }

    private double calculateAverageResponseTime() {
        if (totalRequests.get() == 0) return 0.0;
        return totalResponseTime.get() / (double) totalRequests.get();
    }
}

class ApiEndpointMetrics {
    private final String endpoint;
    private final AtomicInteger callCount;
    private final AtomicInteger errorCount;
    private final AtomicLong totalResponseTime;
    private final List<Long> responseTimes;

    public ApiEndpointMetrics(String endpoint) {
        this.endpoint = endpoint;
        this.callCount = new AtomicInteger(0);
        this.errorCount = new AtomicInteger(0);
        this.totalResponseTime = new AtomicLong(0);
        this.responseTimes = Collections.synchronizedList(new ArrayList<>());
    }

    public void recordCall(int statusCode, long responseTimeMs) {
        callCount.incrementAndGet();
        totalResponseTime.addAndGet(responseTimeMs);
        responseTimes.add(responseTimeMs);

        if (statusCode >= 400) {
            errorCount.incrementAndGet();
        }
    }

    public EndpointPerformance generateEndpointPerformance() {
        EndpointPerformance performance = new EndpointPerformance();
        performance.setEndpoint(endpoint);
        performance.setCallCount(callCount.get());
        performance.setErrorCount(errorCount.get());

        if (callCount.get() > 0) {
            performance.setAverageResponseTime(totalResponseTime.get() / (double) callCount.get());
            performance.setSuccessRate(((callCount.get() - errorCount.get()) * 100.0) / callCount.get());

            // Calculate percentiles
            List<Long> sortedTimes = new ArrayList<>(responseTimes);
            Collections.sort(sortedTimes);

            performance.setP50ResponseTime(calculatePercentile(sortedTimes, 50));
            performance.setP90ResponseTime(calculatePercentile(sortedTimes, 90));
            performance.setP95ResponseTime(calculatePercentile(sortedTimes, 95));
            performance.setP99ResponseTime(calculatePercentile(sortedTimes, 99));
        }

        return performance;
    }

    private long calculatePercentile(List<Long> values, double percentile) {
        if (values.isEmpty()) return 0;
        int index = (int) Math.ceil((percentile / 100.0) * values.size()) - 1;
        return values.get(Math.max(0, Math.min(index, values.size() - 1)));
    }
}

// Jenkinsfile for API Test Automation
pipeline {
    agent {
        docker {
            image 'maven:3.8.4-openjdk-11'
            args '-v /var/run/docker.sock:/var/run/docker.sock'
        }
    }

    environment {
        // Configuration from Jenkins credentials
        API_BASE_URL = credentials('api-base-url')
        API_CLIENT_ID = credentials('api-client-id')
        API_CLIENT_SECRET = credentials('api-client-secret')

        // Test configuration
        TEST_ENVIRONMENT = 'ci'
        TEST_PARALLEL_THREADS = '5'
        TEST_REPORT_DIR = 'target/test-reports'

        // Build information
        BUILD_VERSION = "${env.BUILD_NUMBER}"
        GIT_COMMIT_SHORT = sh(script: 'git rev-parse --short HEAD', returnStdout: true).trim()
        GIT_BRANCH_NAME = "${env.BRANCH_NAME}"
    }

    options {
        timeout(time: 30, unit: 'MINUTES')
        buildDiscarder(logRotator(numToKeepStr: '10'))
        disableConcurrentBuilds()
    }

    parameters {
        booleanParam(name: 'RUN_CONTRACT_TESTS', defaultValue: false, description: 'Run contract tests')
        booleanParam(name: 'RUN_INTEGRATION_TESTS', defaultValue: false, description: 'Run integration tests')
        booleanParam(name: 'RUN_PERFORMANCE_TESTS', defaultValue: false, description: 'Run performance tests')
    }

    stages {
        stage('Checkout') {
            steps {
                checkout scm

                // Display build information
                script {
                    echo "Building branch: ${GIT_BRANCH_NAME}"
                    echo "Git commit: ${GIT_COMMIT_SHORT}"
                    echo "Build number: ${BUILD_VERSION}"
                }
            }
        }

        stage('Build') {
            steps {
                script {
                    sh """
                    mvn clean compile \
                        -DskipTests \
                        -Denvironment=${TEST_ENVIRONMENT}
                    """
                }
            }
        }

        stage('Unit Tests') {
            steps {
                script {
                    sh """
                    mvn test \
                        -Dtest=*UnitTest \
                        -Denvironment=${TEST_ENVIRONMENT} \
                        -Dparallel.threads=${TEST_PARALLEL_THREADS}
                    """
                }
            }
            post {
                always {
                    junit 'target/surefire-reports/**/*.xml'
                    archiveArtifacts 'target/surefire-reports/**/*.txt'
                }
            }
        }

        stage('API Contract Tests') {
            when {
                anyOf {
                    branch 'main'
                    branch 'develop'
                    expression { params.RUN_CONTRACT_TESTS == true }
                }
            }
            steps {
                script {
                    sh """
                    mvn test \
                        -Dtest=*ContractTest \
                        -Denvironment=${TEST_ENVIRONMENT} \
                        -Dpact.provider.version=${BUILD_VERSION} \
                        -Dpact.verifier.publishResults=true
                    """
                }
            }
            post {
                always {
                    junit 'target/pact-results/**/*.xml'
                    archiveArtifacts 'target/pact-results/**/*.json'
                }
            }
        }

        stage('API Functional Tests') {
            steps {
                script {
                    // Escape credentials for shell
                    def apiBaseUrl = sh(script: 'echo "$API_BASE_URL"', returnStdout: true).trim()

                    sh """
                    mvn test \
                        -Dtest=*FunctionalTest \
                        -Denvironment=${TEST_ENVIRONMENT} \
                        -Dapi.baseUrl='${apiBaseUrl}' \
                        -Dparallel.threads=${TEST_PARALLEL_THREADS}
                    """
                }
            }
            post {
                always {
                    junit 'target/failsafe-reports/**/*.xml'
                    archiveArtifacts artifacts: "${TEST_REPORT_DIR}/**/*", 
                                  allowEmptyArchive: true

                    // Generate and publish HTML report
                    script {
                        sh 'mvn site -DgenerateReports=true'
                        publishHTML(target: [
                            allowMissing: false,
                            alwaysLinkToLastBuild: true,
                            keepAll: true,
                            reportDir: 'target/site',
                            reportFiles: 'index.html',
                            reportName: 'API Test Report'
                        ])
                    }
                }
            }
        }

        stage('API Integration Tests') {
            when {
                anyOf {
                    branch 'main'
                    branch 'develop'
                    expression { params.RUN_INTEGRATION_TESTS == true }
                }
            }
            steps {
                script {
                    // Start dependent services
                    sh 'docker-compose -f docker-compose.test.yml up -d'

                    // Wait for services to be ready
                    sh '''
                        timeout 120 bash -c 'until curl -s http://localhost:8080/health > /dev/null; do 
                            echo "Waiting for services..."
                            sleep 5
                        done'
                    '''

                    // Run integration tests
                    sh '''
                        mvn test \
                            -Dtest=*IntegrationTest \
                            -Denvironment=${TEST_ENVIRONMENT} \
                            -Dapi.baseUrl=http://localhost:8080 \
                            -Dparallel.threads=3
                    '''
                }
            }
            post {
                always {
                    script {
                        // Stop services
                        sh 'docker-compose -f docker-compose.test.yml down'

                        junit 'target/failsafe-reports/**/*.xml'
                        archiveArtifacts 'target/failsafe-reports/**/*.txt'
                    }
                }
            }
        }

        stage('API Performance Tests') {
            when {
                anyOf {
                    branch 'main'
                    expression { params.RUN_PERFORMANCE_TESTS == true }
                }
            }
            steps {
                script {
                    // Start application for performance testing
                    sh 'docker-compose -f docker-compose.perf.yml up -d'

                    // Wait for application to be ready
                    sh 'sleep 30'

                    // Get performance API URL from credentials
                    def perfApiUrl = sh(script: 'echo "$PERF_API_BASE_URL"', returnStdout: true).trim()

                    // Run performance tests
                    sh """
                    mvn gatling:test \
                        -Dgatling.simulationClass=com.company.api.performance.UserLoadTest \
                        -Denvironment=perf \
                        -Dapi.baseUrl='${perfApiUrl}' \
                        -Dusers=100 \
                        -Dduration=300
                    """
                }
            }
            post {
                always {
                    script {
                        // Stop application
                        sh 'docker-compose -f docker-compose.perf.yml down'

                        // Archive performance reports
                        archiveArtifacts 'target/gatling/**/*'

                        // Publish performance trends
                        perfReport '**/*/simulation.log'
                    }
                }
            }
        }

        stage('Security Tests') {
            when {
                branch 'main'
            }
            steps {
                script {
                    sh '''
                    mvn test \
                        -Dtest=*SecurityTest \
                        -Denvironment=${TEST_ENVIRONMENT} \
                        -Dsecurity.scan.level=high
                    '''

                    // Run OWASP dependency check
                    sh 'mvn org.owasp:dependency-check-maven:check -Dformat=HTML -Dformat=XML'
                }
            }
            post {
                always {
                    junit 'target/**/TEST-*.xml'
                    archiveArtifacts 'target/dependency-check-report.html'
                }
            }
        }

        stage('Quality Gate') {
            steps {
                script {
                    // Check if summary file exists
                    def summaryFile = "${TEST_REPORT_DIR}/summary.json"
                    def fileExists = fileExists(summaryFile)

                    if (fileExists) {
                        // Analyze test results
                        def testResults = readJSON file: summaryFile

                        // Check pass rate
                        def passRate = testResults.passRate ?: 0
                        if (passRate < 95) {
                            error "Quality gate failed: Pass rate ${passRate}% is below 95% threshold"
                        }

                        // Check performance metrics
                        def avgResponseTime = testResults.performance?.avgResponseTime ?: 0
                        if (avgResponseTime > 1000) {
                            echo "Warning: Average response time ${avgResponseTime}ms is above 1 second"
                        }

                        echo "Quality gate passed: ${passRate}% pass rate"
                    } else {
                        echo "No summary file found at ${summaryFile}, skipping quality gate"
                    }
                }
            }
        }
    }

    post {
        always {
            script {
                // Cleanup workspace
                cleanWs()

                // Update build status
                currentBuild.description = "${GIT_BRANCH_NAME} - ${GIT_COMMIT_SHORT}"

                if (currentBuild.result == 'SUCCESS') {
                    emailext(
                        subject: "✅ Build ${currentBuild.displayName} succeeded",
                        body: "Build ${env.BUILD_URL} completed successfully.",
                        to: 'team@company.com'
                    )
                } else if (currentBuild.result == 'FAILURE') {
                    emailext(
                        subject: "❌ Build ${currentBuild.displayName} failed",
                        body: "Build ${env.BUILD_URL} failed. Please check the logs.",
                        to: 'team@company.com',
                        attachLog: true
                    )
                }
            }
        }

        success {
            script {
                // Update deployment dashboard
                def dashboardUrl = 'https://dashboard.company.com/api/builds'
                def payload = """{
                    "buildNumber": "${env.BUILD_NUMBER}",
                    "status": "SUCCESS",
                    "branch": "${GIT_BRANCH_NAME}",
                    "commit": "${GIT_COMMIT_SHORT}",
                    "timestamp": "${new Date().format('yyyy-MM-dd\'T\'HH:mm:ssZ')}"
                }"""

                sh """
                curl -X POST '${dashboardUrl}' \
                    -H 'Content-Type: application/json' \
                    -d '${payload}'
                """
            }
        }

        failure {
            script {
                // Send notification to Slack
                slackSend(
                    channel: '#build-failures',
                    color: 'danger',
                    message: "Build ${env.JOB_NAME} #${env.BUILD_NUMBER} failed: ${env.BUILD_URL}",
                    failOnError: false
                )
            }
        }

        cleanup {
            script {
                // Clean up any remaining containers
                sh '''
                    docker-compose -f docker-compose.test.yml down 2>/dev/null || true
                    docker-compose -f docker-compose.perf.yml down 2>/dev/null || true
                    docker system prune -f 2>/dev/null || true
                '''
            }
        }
    }
}

