package com.example.jmeter.plugin;

import org.apache.jmeter.config.Arguments;
import org.apache.jmeter.samplers.AbstractSampler;
import org.apache.jmeter.samplers.Entry;
import org.apache.jmeter.samplers.SampleResult;
import org.apache.jmeter.testelement.TestElement;
import org.apache.jmeter.testelement.property.JMeterProperty;

import java.io.Serializable;
import java.util.concurrent.atomic.AtomicLong;

/**
 * Custom JMeter Sampler for specialized protocol testing
 */
public class CustomProtocolSampler extends AbstractSampler implements Serializable {

    private static final long serialVersionUID = 1L;
    private static final AtomicLong ID_COUNTER = new AtomicLong(0);

    // Property keys
    public static final String PROTOCOL = "CustomProtocol.protocol";
    public static final String HOST = "CustomProtocol.host";
    public static final String PORT = "CustomProtocol.port";
    public static final String TIMEOUT = "CustomProtocol.timeout";

    public CustomProtocolSampler() {
        setName("Custom Protocol Sampler");
    }

    @Override
    public SampleResult sample(Entry entry) {
        SampleResult result = new SampleResult();
        result.setSampleLabel(getName());
        result.setSamplerData(buildRequestData());
        result.setDataType(SampleResult.TEXT);

        long startTime = System.currentTimeMillis();
        result.sampleStart();

        try {
            // Custom protocol implementation
            String response = executeCustomProtocol();

            result.sampleEnd();
            result.setSuccessful(true);
            result.setResponseCode("200");
            result.setResponseMessage("OK");
            result.setResponseData(response, "UTF-8");

            // Add custom metrics
            result.setResponseHeaders("Custom-Header: Value\n");

        } catch (Exception e) {
            result.sampleEnd();
            result.setSuccessful(false);
            result.setResponseCode("500");
            result.setResponseMessage(e.getMessage());
            result.setResponseData(e.toString(), "UTF-8");
        }

        return result;
    }

    private String buildRequestData() {
        return String.format("Protocol: %s, Host: %s, Port: %s",
            getProtocol(), getHost(), getPort());
    }

    private String executeCustomProtocol() throws Exception {
        // Implement custom protocol logic here
        Thread.sleep(100); // Simulate processing
        return "Custom Protocol Response: " + System.currentTimeMillis();
    }

    // Getters and setters for properties
    public String getProtocol() { return getPropertyAsString(PROTOCOL); }
    public void setProtocol(String protocol) { setProperty(PROTOCOL, protocol); }

    public String getHost() { return getPropertyAsString(HOST); }
    public void setHost(String host) { setProperty(HOST, host); }

    public int getPort() { return getPropertyAsInt(PORT, 8080); }
    public void setPort(int port) { setProperty(PORT, port); }

    public int getTimeout() { return getPropertyAsInt(TIMEOUT, 5000); }
    public void setTimeout(int timeout) { setProperty(TIMEOUT, timeout); }
}

