package com.example.jmeter.functions;

import org.apache.jmeter.engine.util.CompoundVariable;
import org.apache.jmeter.functions.AbstractFunction;
import org.apache.jmeter.functions.InvalidVariableException;
import org.apache.jmeter.samplers.SampleResult;
import org.apache.jmeter.samplers.Sampler;
import org.apache.jmeter.threads.JMeterVariables;

import java.util.Collection;
import java.util.LinkedList;
import java.util.List;

public class CustomHashFunction extends AbstractFunction {

    private static final List<String> DESC = new LinkedList<>();
    private static final String KEY = "__customHash";

    static {
        DESC.add("Generate custom hash for given input");
        DESC.add("Input string to hash");
        DESC.add("Name of variable to store result (optional)");
    }

    private CompoundVariable input;
    private CompoundVariable varName;

    @Override
    public String execute(SampleResult previousResult, Sampler currentSampler)
            throws InvalidVariableException {

        String inputValue = input.execute();
        String hash = calculateHash(inputValue);

        if (varName != null) {
            String var = varName.execute().trim();
            if (var.length() > 0) {
                JMeterVariables vars = getVariables();
                if (vars != null) {
                    vars.put(var, hash);
                }
            }
        }

        return hash;
    }

    private String calculateHash(String input) {
        // Custom hash algorithm
        int hash = 7;
        for (int i = 0; i < input.length(); i++) {
            hash = hash * 31 + input.charAt(i);
        }
        return Integer.toHexString(hash);
    }
}

