                    git branch: 'main',
                        url: 'https://github.com/company/performance-tests.git'

                    // Setup test configuration
                    sh '''
                    mkdir -p ${WORKSPACE}/results
                    mkdir -p ${WORKSPACE}/reports

                    # Generate environment-specific config
                    cat > ${WORKSPACE}/test-config.properties << EOF
                    application.name=${APPLICATION_NAME}
                    test.type=${TEST_TYPE}
                    target.users=${TARGET_USERS}
                    test.duration=${TEST_DURATION}
                    performance.sla=${PERFORMANCE_SLA}
                    error.threshold=${ERROR_THRESHOLD}
                    influxdb.url=http://localhost:8086
                    influxdb.token=${INFLUXDB_TOKEN}
                    influxdb.org=performance
                    influxdb.bucket=jmeter-metrics
                    EOF
                    '''
                }
            }
        }

        stage('Execute Performance Tests') {
            parallel {
                stage('Baseline Load Test') {
                    steps {
                        script {
                            // Run baseline test
                            runPerformanceTest(
                                testPlan: 'baseline-load.jmx',
                                resultsFile: 'baseline-results.jtl',
                                reportDir: 'baseline-report',
                                properties: [
                                    'users': '100',
                                    'rampup': '60',
                                    'duration': '120'
                                ]
                            )
                        }
                    }
                }

                stage('Main Load Test') {
                    steps {
                        script {
                            // Run main performance test
                            runPerformanceTest(
                                testPlan: 'main-load.jmx',
                                resultsFile: 'main-results.jtl',
                                reportDir: 'main-report',
                                properties: [
                                    'users': params.TARGET_USERS,
                                    'rampup': '300',
                                    'duration': params.TEST_DURATION
                                ]
                            )
                        }
                    }
                }

                stage('Stress Test') {
                    when {
                        expression { params.TEST_TYPE == 'stress' || params.TEST_TYPE == 'spike' }
                    }
                    steps {
                        script {
                            // Run stress test
                            runPerformanceTest(
                                testPlan: 'stress-test.jmx',
                                resultsFile: 'stress-results.jtl',
                                reportDir: 'stress-report',
                                properties: [
                                    'users': (params.TARGET_USERS.toInteger() * 2).toString(),
                                    'rampup': '30',
                                    'duration': '600'
                                ]
                            )
                        }
                    }
                }
            }
        }

        stage('Analyze Results & Performance Gates') {
            steps {
                script {
                    // Analyze test results
                    def analysisResults = analyzePerformanceResults(
                        resultsFile: 'main-results.jtl',
                        baselineFile: 'baseline-results.jtl',
                        slaConfig: [
                            responseTime: PERFORMANCE_SLA.toInteger(),
                            errorRate: ERROR_THRESHOLD.toFloat(),
                            throughputDegradation: 20  // Max 20% degradation
                        ]
                    )

                    // Apply performance gates
                    applyPerformanceGates(analysisResults)

                    // Generate performance report
                    generatePerformanceReport(
                        analysisResults: analysisResults,
                        reportType: 'html',
                        outputDir: 'performance-report'
                    )
                }
            }
        }

        stage('Visualization & Reporting') {
            steps {
                script {
                    // Upload results to monitoring system
                    sh '''
                    # Send metrics to InfluxDB
                    python3 upload_metrics.py \
                        --results main-results.jtl \
                        --application ${APPLICATION_NAME} \
                        --environment ${PERFORMANCE_ENV} \
                        --version ${GATELINE_VERSION}
                    '''

                    // Generate Grafana dashboard
                    generateGrafanaDashboard(
                        application: APPLICATION_NAME,
                        testId: env.BUILD_ID,
                        dashboardTemplate: 'performance-dashboard.json'
                    )

                    // Publish HTML report
                    publishHTML(
                        target: [
                            allowMissing: false,
                            alwaysLinkToLastBuild: true,
                            keepAll: true,
                            reportDir: 'performance-report',
                            reportFiles: 'index.html',
                            reportName: 'Performance Test Report'
                        ]
                    )
                }
            }
        }
    }

    post {
        always {
            script {
                // Archive artifacts
                archiveArtifacts artifacts: 'results/**,reports/**,performance-report/**', allowEmptyArchive: true

                // Cleanup resources
                sh 'rm -rf ${WORKSPACE}/tmp'
            }
        }
        success {
            script {
                // Send success notification
                slackSend(
                    channel: '#performance-success',
                    color: 'good',
                    message: "Performance test passed for ${APPLICATION_NAME}: ${env.BUILD_URL}"
                )

                // Update performance baseline
                updatePerformanceBaseline(
                    application: APPLICATION_NAME,
                    resultsFile: 'main-results.jtl',
                    version: GATELINE_VERSION
                )
            }
        }
        failure {
            script {
                // Send failure notification with details
                def failureReason = currentBuild.getBuildCauses()[0].getShortDescription()
                slackSend(
                    channel: '#performance-failures',
                    color: 'danger',
                    message: "Performance test failed for ${APPLICATION_NAME}: ${failureReason}. Build: ${env.BUILD_URL}"
                )

                // Create JIRA ticket for performance regression
                createJiraIssue(
                    project: 'PERF',
                    summary: "Performance regression detected in ${APPLICATION_NAME}",
                    description: "Build ${env.BUILD_URL} failed performance gates. Please investigate.",
                    priority: 'High'
                )
            }
        }
        unstable {
            script {
                // Send warning for unstable builds
                slackSend(
                    channel: '#performance-warnings',
                    color: 'warning',
                    message: "Performance test unstable for ${APPLICATION_NAME}: ${env.BUILD_URL}"
                )
            }
        }
    }
}

// Custom pipeline functions
void runPerformanceTest(Map config) {
    def testPlan = config.testPlan
    def resultsFile = config.resultsFile
    def reportDir = config.reportDir
    def properties = config.properties ?: [:]

    // Build properties string
    def propsString = properties.collect { k, v -> "-J${k}=${v}" }.join(' ')

    sh """
    /opt/apache-jmeter-5.6/bin/jmeter -n \
        -t ${testPlan} \
        -l ${WORKSPACE}/results/${resultsFile} \
        -e -o ${WORKSPACE}/reports/${reportDir} \
        ${propsString} \
        -Djmeter.save.saveservice.output_format=xml \
        -Djmeter.save.saveservice.assertion_results=none
    """
}

Map analyzePerformanceResults(Map config) {
    def resultsFile = config.resultsFile
    def baselineFile = config.baselineFile
    def slaConfig = config.slaConfig

    // Parse results and compare with baseline
    def analysisScript = '''
    import groovy.json.JsonOutput

    // Parse JTL results
    def parseResults(file) {
        def results = [:]
        // Implementation for parsing JTL/XML results
        return results
    }

    def currentResults = parseResults("${WORKSPACE}/results/${resultsFile}")
    def baselineResults = parseResults("${WORKSPACE}/results/${baselineFile}")

    // Compare with baseline
    def comparison = [:]
    currentResults.each { label, metrics ->
        def baseline = baselineResults[label]
        if (baseline) {
            comparison[label] = [
                current: metrics,
                baseline: baseline,
                degradation: calculateDegradation(metrics, baseline)
            ]
        }
    }

    // Check SLA compliance
    def slaViolations = []
    currentResults.each { label, metrics ->
        if (metrics.avgResponseTime > slaConfig.responseTime) {
            slaViolations << "Response time violation for ${label}: ${metrics.avgResponseTime}ms > ${slaConfig.responseTime}ms"
        }
        if (metrics.errorRate > slaConfig.errorRate) {
            slaViolations << "Error rate violation for ${label}: ${metrics.errorRate}% > ${slaConfig.errorRate}%"
        }
    }

    return [
        summary: currentResults,
        comparison: comparison,
        slaViolations: slaViolations,
        passed: slaViolations.isEmpty()
    ]
    '''

    // Execute analysis script
    def analysisResults = evaluate(analysisScript)
    return analysisResults
}

void applyPerformanceGates(Map analysisResults) {
    if (!analysisResults.passed) {
        error "Performance gates failed: ${analysisResults.slaViolations.join(', ')}"
    }
}

