// utils/api-client.js - Reusable API client
import http from 'k6/http';
import { check } from 'k6';

export class ApiClient {
  constructor(baseUrl, timeout = '30s') {
    this.baseUrl = baseUrl;
    this.defaultParams = { timeout };
  }

  async get(endpoint, params = {}) {
    const url = `${this.baseUrl}/${endpoint}`;
    const response = http.get(url, { ...this.defaultParams, ...params });

    check(response, {
      [`${endpoint} status 2xx`]: (r) => r.status >= 200 && r.status < 300,
    });

    return response;
  }

  async post(endpoint, body, params = {}) {
    const url = `${this.baseUrl}/${endpoint}`;
    const response = http.post(url, JSON.stringify(body), {
      ...this.defaultParams,
      headers: { 'Content-Type': 'application/json' },
      ...params,
    });

    check(response, {
      [`${endpoint} status 2xx`]: (r) => r.status >= 200 && r.status < 300,
    });

    return response;
  }
}

