      'payment successful': (r) => r.status === 200,
      'order created': (r) => r.json().orderId !== undefined,
    });
  });
}

// Teardown for cloud test reporting
export function teardown(data) {
  console.log(`Cloud test completed. Started at: ${data.testStartTime}`);
  console.log('Results available in k6 Cloud dashboard');
  console.log('APM integration data sent to Datadog and New Relic');
}

// config/environments.js
export const environments = {
  development: {
    name: 'development',
    baseUrl: 'http://localhost:3000',
    thresholds: {
      http_req_duration: ['p(95)<2000'],
      http_req_failed: ['rate<0.05'],
    },
    vus: 5,
    duration: '1m',
    tags: { environment: 'dev' },
  },

  staging: {
    name: 'staging',
    baseUrl: process.env.STAGING_URL || 'https://staging.api.example.com',
    thresholds: {
      http_req_duration: ['p(95)<1000'],
      http_req_failed: ['rate<0.01'],
    },
    vus: 20,
    duration: '5m',
    tags: { environment: 'staging' },
  },

  production: {
    name: 'production',
    baseUrl: process.env.PRODUCTION_URL || 'https://api.example.com',
    thresholds: {
      http_req_duration: ['p(95)<500'],
      http_req_failed: ['rate<0.005'],
    },
    vus: 100,
    duration: '10m',
    tags: { environment: 'production' },
  },
};

// Determine environment based on CI/CD context
export function getEnvironment() {
  // Check environment variables first
  const envName = process.env.ENVIRONMENT || 
                  process.env.NODE_ENV || 
                  'development';

  // Map CI/CD contexts to environments
  if (process.env.GITHUB_REF === 'refs/heads/main') {
    return environments.production;
  } else if (process.env.GITHUB_REF === 'refs/heads/staging') {
    return environments.staging;
  }

  return environments[envName] || environments.development;
}

// Main test configuration
export function getTestConfig() {
  const env = getEnvironment();

  return {
    vus: env.vus,
    duration: env.duration,
    thresholds: env.thresholds,
    tags: env.tags,
    // Add environment-specific execution options
    ...(env.name === 'production' && {
      ext: {
        loadimpact: {
          name: `Production Load Test - ${new Date().toISOString()}`,
          projectID: process.env.K6_CLOUD_PROJECT_ID,
        },
      },
    }),
  };
}

