export default function() {
  // Hard-coded URLs throughout
  let res = http.get('http://api.company.com/health');

  // No error handling
  if (res.status != 200) {
    console.log('Health check failed: ' + res.status);
  }

  // Mixed concerns - testing multiple unrelated endpoints
  res = http.get('http://api.company.com/users');

  // Inline data manipulation
  if (res.json()) {
    let users = res.json();
    if (users.length > 0) {
      // Nested calls without structure
      res = http.get('http://api.company.com/users/' + users[0].id);

      // More console.log debugging
      console.log('User details status: ' + res.status);

      // Testing another endpoint
      res = http.get('http://api.company.com/products');

      if (res.json()) {
        let products = res.json();
        // And another nested call
        res = http.get('http://api.company.com/products/' + products[0].id);
      }
    }
  }

  // Random endpoint at the end
  res = http.get('http://api.company.com/config');

  console.log('Test completed');
}

