// Node.js service with OpenTelemetry instrumentation
const { NodeTracerProvider } = require('@opentelemetry/sdk-trace-node');
const { SimpleSpanProcessor } = require('@opentelemetry/sdk-trace-base');
const { OTLPTraceExporter } = require('@opentelemetry/exporter-trace-otlp-grpc');
const { Resource } = require('@opentelemetry/resources');
const { SemanticResourceAttributes } = require('@opentelemetry/semantic-conventions');
const { registerInstrumentations } = require('@opentelemetry/instrumentation');
const { HttpInstrumentation } = require('@opentelemetry/instrumentation-http');
const { ExpressInstrumentation } = require('@opentelemetry/instrumentation-express');
const { WinstonInstrumentation } = require('@opentelemetry/instrumentation-winston');

// Configure OpenTelemetry
const provider = new NodeTracerProvider({
  resource: new Resource({
    [SemanticResourceAttributes.SERVICE_NAME]: 'booking-service',
    [SemanticResourceAttributes.SERVICE_VERSION]: '1.0.0',
    [SemanticResourceAttributes.DEPLOYMENT_ENVIRONMENT]: process.env.NODE_ENV || 'development',
    'service.team': 'platform-engineering',
    'service.criticality': 'p0',
  }),
});

// Configure exporter to APM backend
const exporter = new OTLPTraceExporter({
  url: process.env.OTLP_ENDPOINT || 'http://otel-collector:4317',
  headers: {},
  compression: 'gzip',
});

// Configure sampling based on environment
const samplingRate = process.env.NODE_ENV === 'production' ? 0.1 : 1.0; // 10% in production
provider.addSpanProcessor(
  new SimpleSpanProcessor(exporter, {
    samplingRate,
  })
);

// Register automatic instrumentation
registerInstrumentations({
  tracerProvider: provider,
  instrumentations: [
    new HttpInstrumentation({
      requestHook: (span, request) => {
        span.setAttribute('http.client_ip', request.headers['x-forwarded-for']);
        span.setAttribute('http.user_agent', request.headers['user-agent']);
      },
      responseHook: (span, response) => {
        span.setAttribute('http.response_size', response.headers['content-length']);
      },
    }),
    new ExpressInstrumentation({
      ignoreLayersType: ['middleware', 'request_handler'],
    }),
    new WinstonInstrumentation({
      logHook: (span, record) => {
        record['trace_id'] = span.spanContext().traceId;
        record['span_id'] = span.spanContext().spanId;
      },
    }),
  ],
});

// Register provider
provider.register();

// Manual instrumentation example
const { trace } = require('@opentelemetry/api');
const tracer = trace.getTracer('booking-service');

async function processBooking(bookingData) {
  // Create a custom span for business transaction
  return tracer.startActiveSpan('process-booking', async (span) => {
    try {
      span.setAttributes({
        'booking.id': bookingData.id,
        'booking.amount': bookingData.amount,
        'booking.currency': bookingData.currency,
        'user.id': bookingData.userId,
      });

      // Record events within the span
      span.addEvent('booking-validation-started');

      // Business logic with timing
      const validationStart = Date.now();
      await validateBooking(bookingData);
      span.setAttribute('validation.duration_ms', Date.now() - validationStart);

      span.addEvent('payment-processing-started');

      const paymentResult = await processPayment(bookingData);
      span.setAttribute('payment.status', paymentResult.status);
      span.setAttribute('payment.transaction_id', paymentResult.transactionId);

      span.addEvent('booking-confirmation-sent');
      await sendConfirmation(bookingData);

      span.setStatus({ code: 1 }); // OK
      return { success: true, bookingId: bookingData.id };

    } catch (error) {
      // Record error in span
      span.recordException(error);
      span.setStatus({
        code: 2, // ERROR
        message: error.message,
      });

      span.setAttributes({
        'error.type': error.constructor.name,
        'error.message': error.message,
        'error.stack': error.stack,
      });

      throw error;

    } finally {
      span.end();
    }
  });
}

